export type StaticApiModel = { id: string; object?: string; owned_by?: string; capabilities?: string[]; capability?: "image" | "video" | "text" | "audio"; apiFormat?: GeminiImageApiFormat };
export type CreativeApiConnection = { id: string; name: string; baseUrl: string; key: string; apiFormat?: "openai" | "gemini" };
export type CreativeModelCatalog = { connection: Omit<CreativeApiConnection, "key">; models: StaticApiModel[]; error?: string };

export function isImagenModelName(model: string) {
    return /(?:^|[-_.\s/])imagen(?:$|[-_.\s/])/i.test(normalizeImageModelName(model));
}

export function staticModelProtocolLabel(model: Pick<StaticApiModel, "id" | "capability" | "apiFormat"> | string) {
    const id = typeof model === "string" ? normalizeImageModelName(model) : model.id;
    const capability = typeof model === "string" ? inferModelCapability(id) : model.capability || inferModelCapability(id);
    if (capability === "image" && (isNativeGeminiImageModelName(id) || (typeof model !== "string" && model.apiFormat === "gemini"))) return "Gemini 图片";
    if (capability === "image" && isImagenModelName(id)) return "Imagen / OpenAI Images";
    if (capability === "image") return "OpenAI Images";
    if (capability === "video") return "视频";
    if (capability === "audio") return "音频";
    return "文本 / 推理";
}

export function getCreativeApiConnections(): CreativeApiConnection[] {
    const stored = readConnections();
    if (stored.length) return stored;
    const legacyKey = sessionStorage.getItem(API_KEY_SESSION) || localStorage.getItem(API_KEY_REMEMBERED) || "";
    const legacyBase = sessionStorage.getItem(API_BASE_SESSION) || localStorage.getItem(API_BASE_REMEMBERED) || DEFAULT_CREATIVE_API_BASE_URL;
    if (!legacyKey) return [];
    return [{ id: "default", name: "默认中转站", baseUrl: normalizeApiBaseUrl(legacyBase), key: legacyKey }];
}

export function getCreativeApiConnectionSummaries() {
    return getCreativeApiConnections().map(({ key: _key, ...connection }) => connection);
}

export function getActiveCreativeApiConnection() {
    const connections = getCreativeApiConnections();
    const activeId = sessionStorage.getItem(API_ACTIVE_CONNECTION_SESSION) || localStorage.getItem(API_ACTIVE_CONNECTION_REMEMBERED);
    return connections.find((connection) => connection.id === activeId) || connections[0];
}

export function getCreativeApiKey() {
    return getActiveCreativeApiConnection()?.key || sessionStorage.getItem(API_KEY_SESSION) || localStorage.getItem(API_KEY_REMEMBERED) || "";
}

export function getCreativeApiBaseUrl() {
    const stored = getActiveCreativeApiConnection()?.baseUrl || sessionStorage.getItem(API_BASE_SESSION) || localStorage.getItem(API_BASE_REMEMBERED);
    try {
        return normalizeApiBaseUrl(stored || DEFAULT_CREATIVE_API_BASE_URL);
    } catch {
        sessionStorage.removeItem(API_BASE_SESSION);
        localStorage.removeItem(API_BASE_REMEMBERED);
        return DEFAULT_CREATIVE_API_BASE_URL;
    }
}

export function setCreativeApiKey(value: string, remember = false) {
    const key = value.trim();
    if (key) sessionStorage.setItem(API_KEY_SESSION, key);
    else sessionStorage.removeItem(API_KEY_SESSION);
    if (remember && key) localStorage.setItem(API_KEY_REMEMBERED, key);
    if (!remember) localStorage.removeItem(API_KEY_REMEMBERED);
}

export function setCreativeApiConnection(baseUrl: string, key: string, remember = false) {
    const normalizedBaseUrl = normalizeApiBaseUrl(baseUrl);
    const trimmedKey = key.trim();
    if (!trimmedKey) throw new Error("请输入 API Key");
    const current = getActiveCreativeApiConnection();
    saveCreativeApiConnections([{ id: current?.id || "default", name: current?.name || "默认中转站", baseUrl: normalizedBaseUrl, key: trimmedKey }], current?.id || "default", remember);
}

export function saveCreativeApiConnections(connections: CreativeApiConnection[], activeId?: string, remember = false) {
    const normalized = connections
        .map((connection, index) => ({
            id: connection.id.trim() || `connection-${index + 1}`,
            name: connection.name.trim() || `中转站 ${index + 1}`,
            baseUrl: normalizeApiBaseUrl(connection.baseUrl),
            key: connection.key.trim(),
        }))
        .filter((connection) => connection.baseUrl && connection.key);
    const nextActiveId = normalized.some((connection) => connection.id === activeId) ? activeId! : normalized[0]?.id || "";
    sessionStorage.setItem(API_CONNECTIONS_SESSION, JSON.stringify(normalized));
    if (nextActiveId) sessionStorage.setItem(API_ACTIVE_CONNECTION_SESSION, nextActiveId);
    else sessionStorage.removeItem(API_ACTIVE_CONNECTION_SESSION);
    sessionStorage.setItem(API_BASE_SESSION, normalized.find((connection) => connection.id === nextActiveId)?.baseUrl || "");
    sessionStorage.setItem(API_KEY_SESSION, normalized.find((connection) => connection.id === nextActiveId)?.key || "");
    if (remember) {
        localStorage.setItem(API_CONNECTIONS_REMEMBERED, JSON.stringify(normalized));
        if (nextActiveId) localStorage.setItem(API_ACTIVE_CONNECTION_REMEMBERED, nextActiveId);
    } else {
        localStorage.removeItem(API_CONNECTIONS_REMEMBERED);
        localStorage.removeItem(API_ACTIVE_CONNECTION_REMEMBERED);
        localStorage.removeItem(API_KEY_REMEMBERED);
        localStorage.removeItem(API_BASE_REMEMBERED);
    }
}

export function setActiveCreativeApiConnection(id: string) {
    const connections = getCreativeApiConnections();
    if (!connections.some((connection) => connection.id === id)) throw new Error("中转站连接不存在");
    sessionStorage.setItem(API_ACTIVE_CONNECTION_SESSION, id);
    const connection = connections.find((item) => item.id === id)!;
    sessionStorage.setItem(API_BASE_SESSION, connection.baseUrl);
    sessionStorage.setItem(API_KEY_SESSION, connection.key);
}

export function removeCreativeApiConnection(id: string, remember = Boolean(localStorage.getItem(API_CONNECTIONS_REMEMBERED))) {
    const remaining = getCreativeApiConnections().filter((connection) => connection.id !== id);
    const active = getActiveCreativeApiConnection();
    saveCreativeApiConnections(remaining, active?.id === id ? remaining[0]?.id : active?.id, remember);
}

export function clearCreativeApiKey() {
    sessionStorage.removeItem(API_KEY_SESSION);
    localStorage.removeItem(API_KEY_REMEMBERED);
}

export function clearCreativeApiConnection() {
    sessionStorage.removeItem(API_KEY_SESSION);
    sessionStorage.removeItem(API_BASE_SESSION);
    localStorage.removeItem(API_KEY_REMEMBERED);
    localStorage.removeItem(API_BASE_REMEMBERED);
    sessionStorage.removeItem(API_CONNECTIONS_SESSION);
    sessionStorage.removeItem(API_ACTIVE_CONNECTION_SESSION);
    localStorage.removeItem(API_CONNECTIONS_REMEMBERED);
    localStorage.removeItem(API_ACTIVE_CONNECTION_REMEMBERED);
}

export async function loadCreativeModels(connectionId?: string): Promise<StaticApiModel[]> {
    const connection = getCreativeApiConnection(connectionId);
    if (!connection) throw new Error("尚未配置中转站连接");
    return loadCreativeModelsForConnection(connection);
}

export async function loadCreativeModelsForConnection(connection: CreativeApiConnection): Promise<StaticApiModel[]> {
    const requestConnection = { ...connection, baseUrl: normalizeApiBaseUrl(connection.baseUrl), key: connection.key.trim() };
    let response = await fetchModelCatalog("/v1/models", requestConnection);
    if (!response.ok && [404, 405].includes(response.status)) response = await fetchModelCatalog("/v1beta/models", requestConnection);
    if (!response.ok) throw new Error(await readError(response, "模型列表加载失败"));
    // 【修复】检查响应是否为JSON，避免出现 "Unexpected token" 技术错误
    const contentType = response.headers.get("content-type") || "";
    if (!contentType.includes("application/json") && !contentType.includes("text/json")) {
        const textPreview = await response.text().then((text) => text.slice(0, 200)).catch(() => "");
        throw new Error(`中转站返回了非JSON响应（Content-Type: ${contentType || "未知"}）。请检查中转站地址是否正确，或中转站API是否正常工作。响应预览：${textPreview}`);
    }
    let payload: { data?: unknown; models?: unknown };
    try {
        payload = await response.json() as { data?: unknown; models?: unknown };
    } catch (cause) {
        const textPreview = await response.text().then((text) => text.slice(0, 200)).catch(() => "");
        throw new Error(`中转站返回的响应不是有效的JSON格式。请检查中转站地址是否正确，或中转站API是否正常工作。响应预览：${textPreview}`);
    }
    const values = Array.isArray(payload.data) ? payload.data : Array.isArray(payload.models) ? payload.models : [];
    const models: StaticApiModel[] = values.flatMap((item): StaticApiModel[] => {
        if (typeof item === "string") {
            const id = normalizeImageModelName(item);
            // 【多中转站兼容】不要根据模型名称自动设置 apiFormat 为 "gemini"
            // 中转站通常使用 OpenAI 兼容格式，只有明确配置为 gemini 时才使用原生格式
            return id ? [{ id, capability: isNativeGeminiImageModelName(id) ? "image" : inferModelCapability(id) }] : [];
        }
        if (!item || typeof item !== "object") return [];
        const record = item as Record<string, unknown>;
        const capabilities = Array.isArray(record.capabilities) ? record.capabilities.filter((value): value is string => typeof value === "string") : Array.isArray(record.supportedGenerationMethods) ? record.supportedGenerationMethods.filter((value): value is string => typeof value === "string") : undefined;
        const rawId = typeof record.id === "string" ? record.id : typeof record.name === "string" ? record.name : "";
        const id = normalizeImageModelName(rawId);
        // 【多中转站兼容】只有当 record.apiFormat 或 record.api_format 明确为 "gemini" 时，才设置 apiFormat 为 "gemini"
        // 不要根据模型名称自动设置，因为中转站通常使用 OpenAI 兼容格式
        const apiFormat: GeminiImageApiFormat | undefined = record.apiFormat === "gemini" || record.api_format === "gemini" ? "gemini" : record.apiFormat === "openai" || record.api_format === "openai" ? "openai" : undefined;
        const explicitCapability = record.capability === "image" || record.capability === "video" || record.capability === "text" || record.capability === "audio" ? record.capability : undefined;
        const capability = explicitCapability || (isNativeGeminiImageModelName(id) ? "image" : undefined) || capabilityFromHint(capabilities) || inferModelCapability(id);
        return id ? [{ id, object: typeof record.object === "string" ? record.object : undefined, owned_by: typeof record.owned_by === "string" ? record.owned_by : undefined, capabilities, capability, apiFormat }] : [];
    });
    modelCatalogCache.set(requestConnection.id, models);
    return models;
}

async function fetchModelCatalog(path: string, connection: CreativeApiConnection) {
    const controller = new AbortController();
    const timeout = window.setTimeout(() => controller.abort(), MODEL_LIST_TIMEOUT_MS);
    try {
        return await fetchCreativeApiConnection(path, { signal: controller.signal }, connection);
    } catch (error) {
        if (controller.signal.aborted) throw new Error(`获取模型超时（${MODEL_LIST_TIMEOUT_MS / 1000} 秒）：请检查中转站地址、网络或 CORS 设置`);
        throw error;
    } finally {
        window.clearTimeout(timeout);
    }
}

export async function loadCreativeModelCatalogs(): Promise<CreativeModelCatalog[]> {
    const connections = getCreativeApiConnections();
    return Promise.all(connections.map(async ({ key: _key, ...connection }) => {
        try {
            return { connection, models: await loadCreativeModels(connection.id) };
        } catch (error) {
            return { connection, models: [], error: error instanceof Error ? error.message : "模型列表加载失败" };
        }
    }));
}

export function installStaticRuntime() {
    if (runtimeInstalled) return;
    runtimeInstalled = true;
    (window as Window & { __SOCIAL_COW_STATIC__?: boolean }).__SOCIAL_COW_STATIC__ = true;
    window.fetch = ((input: RequestInfo | URL, init?: RequestInit) => {
        const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
        if (!url.startsWith("/api/") || url.startsWith("/api/status")) return originalFetch(input, init);
        return handleStaticRequest(url, init);
    }) as typeof window.fetch;
}

export function isStaticRuntimeInstalled() {
    return runtimeInstalled;
}

export function newApiFetch(path: string, init: RequestInit = {}, connectionId?: string, baseUrlOverride?: string) {
    const requestInit = { ...init } as RequestInit & { connectionId?: string };
    const requestConnectionId = connectionId || requestInit.connectionId;
    delete requestInit.connectionId;
    const headers = new Headers(requestInit.headers);
    const connection = requestConnectionId ? getCreativeApiConnections().find((item) => item.id === requestConnectionId) : getActiveCreativeApiConnection();
    const key = connection?.key || getCreativeApiKey();
    if (key) headers.set("Authorization", `Bearer ${key}`);
    return fetchCreativeApiConnection(path, { ...requestInit, headers }, connection || { id: requestConnectionId || "default", name: "默认中转站", baseUrl: baseUrlOverride || getCreativeApiBaseUrl(), key });
}

function fetchCreativeApiConnection(path: string, init: RequestInit = {}, connection: CreativeApiConnection) {
    const headers = new Headers(init.headers);
    if (connection.key) headers.set("Authorization", `Bearer ${connection.key}`);
    const target = /^https?:\/\//i.test(path) ? path : `${connection.baseUrl}${path.startsWith("/") ? path : `/${path}`}`;
    // 【修复】直接请求中转站，不走代理，避免代理端点返回错误响应
    return originalFetch(target, { ...init, headers });
}

async function handleStaticRequest(url: string, init?: RequestInit): Promise<Response> {
    const parsed = new URL(url, window.location.origin);
    const path = parsed.pathname;
    try {
        if (path === "/api/auth/session") return jsonResponse({ user: staticUser(), settings: { site: { title: "社会牛码创作工作台", logoUrl: "/creative/logo.svg" } } });
        if (path === "/api/auth/logout") return jsonResponse({ ok: true });
        if (path === "/api/install/status") return jsonResponse({ install: { ready: true, firstAdminRequired: false, site: { title: "社会牛码创作工作台", logoUrl: "/creative/logo.svg" } } });
        if (path === "/api/points") return jsonResponse({ data: { pointsBalance: 0, permanentPointsBalance: 0, dailyPointsBalance: 0 } });
        if (path.startsWith("/api/reference-assets/") || path.startsWith("/api/generation-log-assets/")) {
            // /api/<scope>/<storage-key>; keep the permanent/temporary prefix.
            const key = path.split("/").slice(3).map((part) => decodeURIComponent(part)).join("/");
            const media = await findLocalMedia(key);
            if (media) {
                const blob = await (await originalFetch(media.dataUrl)).blob();
                return new Response(blob, { headers: { "Content-Type": media.mimeType, "Cache-Control": "private, max-age=86400" } });
            }
            return jsonResponse({ code: 404, data: null, msg: "本地素材不存在，请重新上传" }, 404);
        }
        if (path.startsWith("/api/canvas/projects")) return handleCanvas(path, parsed.searchParams, init);
        if (path === "/api/canvas/stitch" && (init?.method || "GET") === "POST") return handleCanvasStitch(init);
        if (path === "/api/creative/assets") return handleCreativeAssetUpload(init);
        if (path.startsWith("/api/creative/conversations")) return handleCreativeConversations(path, parsed.searchParams, init);
        if (path === "/api/agent/prompt-optimization") return handleAgentPromptOptimization(init);
        if (path === "/api/agent/skills" || path.startsWith("/api/agent/skills/")) return handleAgentSkill(path, parsed.searchParams, init);
        if (path.startsWith("/api/agent/")) return handleAgent(path, parsed.searchParams, init);
        if (path === "/api/reference-assets") return handleReferenceAsset(init);
        if (path === "/api/media-assets") return jsonResponse({ data: { deletedFiles: 0, blocked: [] } });
        // 【修复】实现外部代理端点，避免生产环境请求失败
        if (path === "/api/external-proxy/request") {
            const targetUrl = init?.headers instanceof Headers ? init.headers.get("X-Target-URL") : (init?.headers as Record<string, string>)?.["X-Target-URL"] || (init?.headers as Record<string, string>)?.["x-target-url"];
            if (!targetUrl) return jsonResponse({ error: "缺少 X-Target-URL 请求头" }, 400);
            try {
                const proxyHeaders = new Headers(init?.headers);
                proxyHeaders.delete("X-Target-URL");
                proxyHeaders.delete("x-target-url");
                const proxyResponse = await originalFetch(targetUrl, { ...init, headers: proxyHeaders });
                const responseBody = await proxyResponse.blob();
                const responseHeaders = new Headers(proxyResponse.headers);
                responseHeaders.set("Access-Control-Allow-Origin", "*");
                return new Response(responseBody, { status: proxyResponse.status, statusText: proxyResponse.statusText, headers: responseHeaders });
            } catch (cause) {
                return jsonResponse({ error: cause instanceof Error ? cause.message : "代理请求失败" }, 502);
            }
        }
        if (path === "/api/image-tasks") return handleImageTask(init);
        if (path.startsWith("/api/image-tasks/")) return handleImageTaskById(path.split("/").pop() || "");
        if (path === "/api/text-tasks") return handleTextTask(init);
        if (path.startsWith("/api/text-tasks/")) return handleTextTaskById(path.split("/").pop() || "");
        if (path === "/api/video-generation-tasks") return handleVideoTask(init);
        if (path.startsWith("/api/video-tasks/")) return handleVideoTaskById(path.split("/").pop() || "");
        if (path === "/api/audio-tasks") return handleAudioTask(init);
        if (path.startsWith("/api/audio-tasks/")) return handleAudioTaskById(path.split("/").pop() || "");
        return jsonResponse({ code: 503, data: null, msg: "尚未配置可用的中转站连接，请在右下角设置中转站地址和 API Key" }, 503);
    } catch (error) {
        if (init?.signal?.aborted) throw error;
        return jsonResponse({ code: 500, data: null, msg: error instanceof Error ? error.message : "请求失败" }, 500);
    }
}

async function handleAgentSkill(path: string, search: URLSearchParams, init?: RequestInit) {
    const method = (init?.method || "GET").toUpperCase();
    const id = path.split("/").filter(Boolean)[3];
    if (method === "GET") {
        const workspace = search.get("workspace") || "all";
        const skills = [...BUILTIN_AGENT_SKILLS, ...(await dbList<StaticAgentSkill>("skills"))];
        const visible = skills
            .filter((skill) => skill.enabled && (workspace === "all" || workspace === "chat" || skill.workspaces.includes(workspace as StaticAgentSkill["workspaces"][number])))
            .sort((left, right) => right.updatedAt - left.updatedAt);
        return jsonResponse({ code: 0, data: { skills: visible }, msg: "OK" });
    }
    if (method === "POST") {
        const input = await readJson(init);
        const normalized = normalizeStaticAgentSkill(input);
        if (!normalized.name || !normalized.instructions) return jsonResponse({ code: 400, data: null, msg: "Skill 名称和执行规则不能为空" }, 400);
        const now = Date.now();
        const skill: StaticAgentSkill = { ...normalized, id: `skill-local-${nanoid()}`, source: "local", enabled: true, keywords: normalizeStaticSkillKeywords(input, normalized), createdAt: now, updatedAt: now };
        await dbPut("skills", skill);
        return jsonResponse({ code: 0, data: { skill }, msg: "Skill 已创建" });
    }
    if (!id) return jsonResponse({ code: 400, data: null, msg: "Skill 标识不能为空" }, 400);
    const current = await dbGet<StaticAgentSkill>("skills", decodeURIComponent(id));
    if (path.endsWith("server-nuyoah-xiezhen-prompt")) return jsonResponse({ code: 403, data: null, msg: "服务器内置 Skill 只能使用，不能编辑或删除" }, 403);
    if (!current) return jsonResponse({ code: 404, data: null, msg: "Skill 不存在" }, 404);
    if (method === "PATCH") {
        const input = await readJson(init);
        const normalized = normalizeStaticAgentSkill({ ...current, ...input });
        if (!normalized.name || !normalized.instructions) return jsonResponse({ code: 400, data: null, msg: "Skill 名称和执行规则不能为空" }, 400);
        const skill = { ...current, ...normalized, keywords: normalizeStaticSkillKeywords(input, normalized, current.keywords), updatedAt: Date.now() };
        await dbPut("skills", skill);
        return jsonResponse({ code: 0, data: { skill }, msg: "Skill 已更新" });
    }
    if (method === "DELETE") {
        await dbDelete("skills", current.id);
        return jsonResponse({ code: 0, data: { deleted: true }, msg: "Skill 已删除" });
    }
    return jsonResponse({ code: 405, data: null, msg: "不支持的请求方法" }, 405);
}

function normalizeStaticAgentSkill(value: Record<string, any>): Omit<StaticAgentSkill, "id" | "source" | "enabled" | "keywords" | "createdAt" | "updatedAt"> {
    const allowed = new Set(["image", "video", "canvas"]);
    const workspaces = (Array.isArray(value.workspaces) ? value.workspaces : ["canvas"]).map((item: unknown) => String(item)).filter((item: string): item is StaticAgentSkill["workspaces"][number] => allowed.has(item));
    return {
        name: String(value.name || "").trim().slice(0, 60),
        description: String(value.description || "").trim().slice(0, 160),
        instructions: String(value.instructions || value.plannerSummary || "").trim().slice(0, 4000),
        plannerSummary: String(value.plannerSummary || value.description || "").trim().slice(0, 240) || undefined,
        action: value.action === "edit" ? "edit" : "generate",
        requiresReference: value.requiresReference === true,
        workspaces: Array.from(new Set(workspaces.length ? workspaces : ["canvas"])),
    };
}

function normalizeStaticSkillKeywords(value: Record<string, any>, normalized: { name: string; description: string; plannerSummary?: string }, fallback: string[] = []) {
    const explicit = Array.isArray(value.keywords) ? value.keywords : [];
    const inferred = [normalized.name, normalized.description, normalized.plannerSummary || ""]
        .flatMap((item) => item.split(/[、,，\s/|]+/))
        .map((item) => item.trim())
        .filter((item) => item.length >= 2);
    return Array.from(new Set([...explicit, ...fallback, ...inferred].map((item) => String(item).trim()).filter((item) => item.length >= 2))).slice(0, 30);
}

async function fetchBuiltinSkillInstructions(id: string) {
    if (id !== "server-nuyoah-xiezhen-prompt") return "";
    const response = await originalFetch(`/collab/skills/${encodeURIComponent(id)}/use`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ surface: "agent" }) });
    if (!response.ok) throw new Error("服务器内置 Skill 暂时不可用，请稍后重试");
    const payload = await response.json() as { instructions?: unknown };
    if (typeof payload.instructions !== "string" || !payload.instructions.trim()) throw new Error("服务器内置 Skill 内容为空");
    return payload.instructions;
}

async function findLocalMedia(key: string) {
    const direct = mediaData.get(key) || await dbGet<{ dataUrl: string; mimeType: string }>("media", key);
    if (direct) return direct;
    // Older local projects sometimes kept only the basename as storageKey.
    const all = await dbList<{ id: string; dataUrl: string; mimeType: string }>("media");
    const matches = all.filter((item) => item.id === key || item.id.endsWith(`/${key}`) || item.id.split("/").at(-1) === key);
    return matches.length === 1 ? matches[0] : undefined;
}

async function handleCanvasStitch(init?: RequestInit) {
    try {
        const body = await readJson(init);
        const rawImages = Array.isArray(body.images) ? body.images.filter((v: unknown): v is string => typeof v === "string" && Boolean(v.trim())).slice(0, 20) : [];
        const direction = body.direction === "horizontal" ? "horizontal" : "vertical";
        const gap = Math.max(0, Math.min(400, Math.floor(Number(body.gap) || 0)));
        const background = typeof body.background === "string" && body.background.trim() ? body.background.trim() : "#ffffff";
        const align = body.align === "start" || body.align === "end" ? body.align : "center";
        if (rawImages.length < 2) return jsonResponse({ code: 400, data: null, msg: "至少需要 2 张图片" }, 400);

        const loaded: { img: HTMLImageElement; width: number; height: number }[] = [];
        for (const src of rawImages) {
            const dataUrl = src.startsWith("data:") ? src : await loadImageAsDataUrl(src);
            const img = await decodeImage(dataUrl);
            loaded.push({ img, width: img.naturalWidth, height: img.naturalHeight });
        }

        const base = loaded[0];
        const normalized = loaded.map((item) => {
            if (direction === "vertical") {
                if (item.width === base.width) return item;
                const w = base.width;
                const h = Math.max(1, Math.round((item.height * w) / item.width));
                return { ...item, width: w, height: h };
            } else {
                if (item.height === base.height) return item;
                const h = base.height;
                const w = Math.max(1, Math.round((item.width * h) / item.height));
                return { ...item, width: w, height: h };
            }
        });

        const totalWidth = direction === "vertical" ? Math.max(...normalized.map((i) => i.width)) : normalized.reduce((s, i) => s + i.width, gap * (normalized.length - 1));
        const totalHeight = direction === "horizontal" ? Math.max(...normalized.map((i) => i.height)) : normalized.reduce((s, i) => s + i.height, gap * (normalized.length - 1));
        if (totalWidth * totalHeight > 120_000_000) return jsonResponse({ code: 413, data: null, msg: "拼接后图片过大，请减少分屏数量" }, 413);

        const canvas = document.createElement("canvas");
        canvas.width = totalWidth;
        canvas.height = totalHeight;
        const ctx = canvas.getContext("2d")!;
        ctx.fillStyle = background;
        ctx.fillRect(0, 0, totalWidth, totalHeight);

        if (direction === "vertical") {
            let top = 0;
            for (const item of normalized) {
                const left = align === "start" ? 0 : align === "end" ? totalWidth - item.width : Math.floor((totalWidth - item.width) / 2);
                ctx.drawImage(item.img, left, top, item.width, item.height);
                top += item.height + gap;
            }
        } else {
            let left = 0;
            for (const item of normalized) {
                const top = align === "start" ? 0 : align === "end" ? totalHeight - item.height : Math.floor((totalHeight - item.height) / 2);
                ctx.drawImage(item.img, left, top, item.width, item.height);
                left += item.width + gap;
            }
        }

        const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
        const bytes = Math.round((dataUrl.length - dataUrl.indexOf(",") - 1) * 0.75);
        return jsonResponse({ code: 0, data: { dataUrl, width: totalWidth, height: totalHeight, bytes, mimeType: "image/jpeg" }, msg: "OK" });
    } catch (error) {
        return jsonResponse({ code: 502, data: null, msg: error instanceof Error ? error.message : "图片拼接失败" }, 502);
    }
}

async function loadImageAsDataUrl(src: string): Promise<string> {
    const response = await fetch(src);
    if (!response.ok) throw new Error("无法读取图片");
    const blob = await response.blob();
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = () => reject(new Error("图片读取失败"));
        reader.readAsDataURL(blob);
    });
}

function decodeImage(dataUrl: string): Promise<HTMLImageElement> {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error("图片解码失败"));
        img.src = dataUrl;
    });
}

async function handleCanvas(path: string, search: URLSearchParams, init?: RequestInit) {
    const parts = path.split("/").filter(Boolean);
    const id = parts[3];
    const method = init?.method || "GET";
    if (!id && method === "GET") {
        const all = await dbList<CanvasProject>("canvas");
        const page = Math.max(1, Number(search.get("page")) || 1);
        const pageSize = Math.max(1, Number(search.get("pageSize")) || 12);
        const ordered = all.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
        return jsonResponse({ code: 0, data: { projects: ordered.slice((page - 1) * pageSize, page * pageSize).map(summarizeCanvasProjectRecord), total: ordered.length, page, pageSize }, msg: "OK" });
    }
    if (!id && method === "DELETE") {
        const input = await readJson(init);
        const ids = Array.isArray(input.ids) ? input.ids.map((item: unknown) => String(item)) : [];
        await Promise.all(ids.map((item: string) => dbDelete("canvas", item)));
        return jsonResponse({ code: 0, data: { deleted: ids.length }, msg: "OK" });
    }
    if (!id && method === "POST") {
        const input = await readJson(init);
        const source = (input.project || {}) as Partial<CanvasProject>;
        const now = new Date().toISOString();
        const project: CanvasProject = { id: `canvas-${nanoid()}`, title: String(input.title || source.title || "未命名画布"), createdAt: now, updatedAt: now, nodes: source.nodes || [], connections: source.connections || [], chatSessions: source.chatSessions || [], activeChatId: source.activeChatId || null, backgroundMode: source.backgroundMode || "lines", showImageInfo: source.showImageInfo === true, viewport: source.viewport || { x: 0, y: 0, k: 1 }, sourceHandoffId: input.sourceHandoffId || source.sourceHandoffId, creativeConversationId: source.creativeConversationId || `conversation-${nanoid()}` };
        await dbPut("canvas", project);
        return jsonResponse({ code: 0, data: { project }, msg: "画布项目已创建" });
    }
    let project = await dbGet<CanvasProject>("canvas", id);
    if (!project && method === "GET" && /^#collab=[\w-]+\.[\w-]+\.(viewer|editor)$/.test(location.hash)) {
        const now = new Date().toISOString();
        project = { id, title: "协作画布", createdAt: now, updatedAt: now, nodes: [], connections: [], chatSessions: [], activeChatId: null, backgroundMode: "lines", showImageInfo: false, viewport: { x: 0, y: 0, k: 1 } };
        await dbPut("canvas", project);
    }
    if (!project) return jsonResponse({ code: 404, data: null, msg: "画布项目不存在" }, 404);
    if (parts.at(-1) === "assistant-conversations" && method === "DELETE") {
        const input = await readJson(init);
        const conversationIds = new Set<string>(Array.isArray(input.conversationIds) ? input.conversationIds.map((item: unknown) => String(item)) : []);
        const chatSessions = project.chatSessions.filter((session) => !conversationIds.has(String(session.conversationId || "")));
        const activeChatId = chatSessions.some((session) => session.id === project.activeChatId) ? project.activeChatId : chatSessions[0]?.id || null;
        await dbPut("canvas", { ...project, chatSessions, activeChatId, updatedAt: new Date().toISOString() });
        for (const conversationId of conversationIds) await deleteStaticCreativeConversation(conversationId);
        return jsonResponse({ code: 0, data: { deleted: conversationIds.size, chatSessions, activeChatId }, msg: "OK" });
    }
    if (method === "GET") return jsonResponse({ code: 0, data: { project }, msg: "OK" });
    if (method === "DELETE") { await dbDelete("canvas", id); return jsonResponse({ code: 0, data: { deleted: 1 }, msg: "OK" }); }
    if (method === "PATCH") {
        const body = await readJson(init);
        const next = body.mutation ? applyCanvasProjectMutation(project, body.mutation as CanvasProjectMutation, new Date().toISOString()) : { ...project, ...(body.project || {}), updatedAt: new Date().toISOString() };
        await dbPut("canvas", next);
        return jsonResponse({ code: 0, data: body.mutation ? { ack: { projectId: id, updatedAt: next.updatedAt, mutationId: body.mutation.mutationId } } : { project: next }, msg: "OK" });
    }
    return jsonResponse({ code: 405, data: null, msg: "不支持的请求方法" }, 405);
}


async function handleReferenceAsset(init?: RequestInit) {
    const body = init?.body;
    if (body instanceof FormData) {
        const file = body.get("file");
        if (file instanceof Blob) {
            const dataUrl = await blobToDataUrl(file);
            const key = `permanent/${nanoid()}`;
            mediaData.set(key, { dataUrl, mimeType: file.type || "application/octet-stream" });
            await dbPut("media", { id: key, dataUrl, mimeType: file.type || "application/octet-stream" });
            return jsonResponse({ token: dataUrl, key, url: dataUrl, bytes: file.size, mimeType: file.type || "application/octet-stream" });
        }
    }
    const input = await readJson(init);
    return jsonResponse({ token: String(input.dataUrl || ""), key: `permanent/${nanoid()}`, url: String(input.dataUrl || ""), upstreamUrl: String(input.dataUrl || "") });
}

async function handleImageTask(init?: RequestInit) {
    const input = await readJson(init);
    const config = input.config || {};
    const references = Array.isArray(input.references) ? input.references : [];
    const rawModel = String(config.model || "");
    const connectionId = String(config.connectionId || connectionIdFromModel(rawModel) || "");
    const model = modelName(rawModel);
    if (!model) return jsonResponse({ error: "请先选择图片模型" }, 400);
    if (!String(input.prompt || "").trim()) return jsonResponse({ error: "请输入图片提示词" }, 400);
    const catalogModel = modelCatalogCache.get(connectionId)?.find((item) => normalizeImageModelName(item.id).toLowerCase() === model.toLowerCase());
    const connection = getCreativeApiConnection(connectionId);
    const path = references.length ? "/v1/images/edits" : "/v1/images/generations";
    // 【多中转站兼容】优先使用 connection 级别的 apiFormat，然后是 config.apiFormat，最后是模型的 apiFormat
    const connectionApiFormat = connection?.apiFormat;
    const effectiveApiFormat = connectionApiFormat || config.apiFormat || catalogModel?.apiFormat;
    if (isGeminiImageModel(model, effectiveApiFormat, catalogModel?.capability || inferModelCapability(model))) {
        return handleGeminiImageTask(config, input, references, model, connectionId);
    }
    const requestSize = normalizeStaticImageSize(config.size, config.quality);
    const attempts = references.length
        ? [
              // 标准 OpenAI Images Edits 字段名：单张 image，多张 image[]
              { path, init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, "url", openAiImageReferenceFieldName(references.length)) } },
              { path, init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, undefined, openAiImageReferenceFieldName(references.length)) } },
              // 兼容 sub2api/new-api 等中转站使用 images 字段名
              { path, init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, "url", "images") } },
              { path, init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, undefined, "images") } },
              // 多张参考图时额外尝试 image 字段名
              ...(references.length > 1 ? [
                  { path, init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, "url", "image") } },
                  { path, init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, undefined, "image") } },
              ] : []),
              // 【多中转站兼容】尝试使用 /v1/images/generations 路径（一些中转站的 Gemini 图片模型不支持 edits 路径）
              { path: "/v1/images/generations", init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, "url", "image") } },
              { path: "/v1/images/generations", init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, "url", "images") } },
              // 【多中转站兼容】尝试使用 file/files 字段名（一些中转站使用这些字段名）
              { path, init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, "url", "file") } },
              { path, init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, "url", "files") } },
              { path: "/v1/images/generations", init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, "url", "file") } },
              { path: "/v1/images/generations", init: { method: "POST", body: await imageEditFormData(config, input, references, requestSize, "url", "files") } },
          ]
        : [
              // JSON 格式（标准 OpenAI Images）
              { path, init: { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(imageGenerationBody(model, input, config, requestSize, "url")) } },
              { path, init: { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(imageGenerationBody(model, input, config, requestSize)) } },
              // form-data 格式（兼容 sub2api 等不支持 JSON 请求体的中转站）
              { path, init: { method: "POST", body: await imageEditFormData(config, input, [], requestSize, "url") } },
              { path, init: { method: "POST", body: await imageEditFormData(config, input, [], requestSize) } },
          ];
    let result: Response | undefined;
    let lastError = "图片生成失败";
    for (const attempt of attempts) {
        result = await newApiFetch(attempt.path, attempt.init, connectionId);
        if (result.ok) break;
        lastError = await readError(result, "图片生成失败");
        if (!shouldRetryImageRequest(result.status, lastError)) break;
    }

    // 【多中转站兼容】多级自动降级尺寸重试
    // 当中转站只配置了部分图片尺寸层级时，更高尺寸会报错 "image size tier is not configured"
    // 此时按 4k → 2k → 1k 的顺序多级降级，保持原始宽高比，直到找到中转站支持的尺寸
    if (!result?.ok && /image size tier is not configured|image_size_tier/i.test(lastError)) {
        // 解析原始尺寸
        const sizeMatch = String(requestSize || "").match(/^(\d+)x(\d+)$/);
        if (sizeMatch) {
            const origW = Number(sizeMatch[1]);
            const origH = Number(sizeMatch[2]);
            if (origW > 0 && origH > 0) {
                const ratio = Math.max(origW, origH) / Math.min(origW, origH);
                const origShort = Math.min(origW, origH);

                // 根据原始短边决定降级顺序（从高到低，跳过比原始尺寸更大的层级）
                const tiers = [
                    { short: 4096, name: "4k" },
                    { short: 2048, name: "2k" },
                    { short: 1024, name: "1k" },
                ].filter(tier => tier.short < origShort); // 只尝试比原始尺寸小的层级

                // 辅助函数：根据短边和比例计算尺寸
                const calcSize = (short: number) => {
                    const long = Math.ceil((short * ratio) / 16) * 16;
                    return origW >= origH ? `${long}x${short}` : `${short}x${long}`;
                };

                // 多级降级重试
                for (const tier of tiers) {
                    const fallbackSize = calcSize(tier.short);
                    if (fallbackSize === requestSize) continue; // 跳过和原始尺寸相同的层级

                    const fallbackAttempts = references.length
                        ? [
                              { path, init: { method: "POST", body: await imageEditFormData(config, input, references, fallbackSize, "url", openAiImageReferenceFieldName(references.length)) } },
                              { path, init: { method: "POST", body: await imageEditFormData(config, input, references, fallbackSize, undefined, openAiImageReferenceFieldName(references.length)) } },
                              { path, init: { method: "POST", body: await imageEditFormData(config, input, references, fallbackSize, "url", "images") } },
                              { path, init: { method: "POST", body: await imageEditFormData(config, input, references, fallbackSize, undefined, "images") } },
                              ...(references.length > 1 ? [
                                  { path, init: { method: "POST", body: await imageEditFormData(config, input, references, fallbackSize, "url", "image") } },
                                  { path, init: { method: "POST", body: await imageEditFormData(config, input, references, fallbackSize, undefined, "image") } },
                              ] : []),
                          ]
                        : [
                              { path, init: { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(imageGenerationBody(model, input, config, fallbackSize, "url")) } },
                              { path, init: { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(imageGenerationBody(model, input, config, fallbackSize)) } },
                              { path, init: { method: "POST", body: await imageEditFormData(config, input, [], fallbackSize, "url") } },
                              { path, init: { method: "POST", body: await imageEditFormData(config, input, [], fallbackSize) } },
                          ];

                    for (const attempt of fallbackAttempts) {
                        result = await newApiFetch(attempt.path, attempt.init, connectionId);
                        if (result.ok) break;
                        lastError = await readError(result, "图片生成失败");
                        if (!shouldRetryImageRequest(result.status, lastError)) break;
                    }

                    if (result?.ok) break; // 成功就停止降级
                    // 如果还是 "image size tier is not configured" 错误，继续降级到下一个层级
                    if (!/image size tier is not configured|image_size_tier/i.test(lastError)) break;
                }
            }
        }
    }

    if (!result?.ok) return jsonResponse({ error: explainImageModelError(lastError, model, result?.status) }, result?.status || 502);
    const response = await result.json() as Record<string, unknown>;
    const upstreamTaskId = String(response.id || response.task_id || ((response.data as Record<string, unknown> | undefined)?.id || ""));
    if (result.status === 202 || (upstreamTaskId && !response.data && !response.images)) {
        const taskId = upstreamTaskId || `image-${nanoid()}`;
        taskConnections.set(taskId, connectionId);
        taskRequests.set(taskId, Promise.resolve(response));
        await rememberStaticImageTask({
            id: taskId,
            connectionId,
            baseUrl: connection?.baseUrl || getCreativeApiBaseUrl(),
            model: String(config.model || model),
            kind: references.length ? "edit" : "generation",
            queryPath: `/v1/images/tasks/${encodeURIComponent(taskId)}`,
            createdAt: Date.now(),
        });
        return jsonResponse({ task: { id: taskId, kind: references.length ? "edit" : "generation", model: config.model, status: "pending" } });
    }
    const taskId = `image-${nanoid()}`;
    taskConnections.set(taskId, connectionId);
    const normalized = normalizeImageResponse(response, connection?.baseUrl || getCreativeApiBaseUrl());
    taskResults.set(taskId, normalized);
    await rememberStaticImageTask({
        id: taskId,
        connectionId,
        baseUrl: connection?.baseUrl || getCreativeApiBaseUrl(),
        model: String(config.model || model),
        kind: references.length ? "edit" : "generation",
        result: normalized,
        createdAt: Date.now(),
    });
    return jsonResponse({ task: { id: taskId, kind: references.length ? "edit" : "generation", model: config.model, status: "success", result: normalized } });
}


/**
 * 【修复】自动压缩图片到 Gemini API 限制的 10MB 以内
 * Gemini API 限制参考图的 base64 编码不能超过 10MB
 * 压缩策略：先降低质量，再缩小尺寸，确保压缩后的图片在 10MB 以内
 */
const GEMINI_MAX_IMAGE_SIZE = 10 * 1024 * 1024; // 10MB

async function compressImageBlobIfNeeded(blob: Blob): Promise<Blob> {
    // 如果图片大小 <= 10MB，不压缩
    if (blob.size <= GEMINI_MAX_IMAGE_SIZE) return blob;
    
    console.log(`[Gemini 图片压缩] 原始大小: ${(blob.size / 1024 / 1024).toFixed(2)}MB，超过 10MB 限制，开始压缩...`);
    
    try {
        // 创建 Image 对象
        const imageBitmap = await createImageBitmap(blob);
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        if (!ctx) return blob;
        
        let width = imageBitmap.width;
        let height = imageBitmap.height;
        let quality = 0.9;
        let compressedBlob = blob;
        
        // 压缩策略：先降低质量（0.9 -> 0.5），然后缩小尺寸
        for (let scale = 1; scale >= 0.3; scale -= 0.1) {
            for (let q = quality; q >= 0.3; q -= 0.1) {
                canvas.width = Math.round(width * scale);
                canvas.height = Math.round(height * scale);
                ctx.drawImage(imageBitmap, 0, 0, canvas.width, canvas.height);
                
                // 转换为 JPEG 格式（比 PNG 小很多）
                compressedBlob = await new Promise<Blob>((resolve) => {
                    canvas.toBlob((b) => resolve(b || blob), "image/jpeg", q);
                });
                
                if (compressedBlob.size <= GEMINI_MAX_IMAGE_SIZE) {
                    console.log(`[Gemini 图片压缩] 压缩成功: ${(compressedBlob.size / 1024 / 1024).toFixed(2)}MB，尺寸: ${canvas.width}x${canvas.height}，质量: ${q.toFixed(1)}`);
                    return compressedBlob;
                }
            }
        }
        
        // 如果还是超过 10MB，强制缩小到 0.3 倍，质量 0.3
        canvas.width = Math.round(width * 0.3);
        canvas.height = Math.round(height * 0.3);
        ctx.drawImage(imageBitmap, 0, 0, canvas.width, canvas.height);
        compressedBlob = await new Promise<Blob>((resolve) => {
            canvas.toBlob((b) => resolve(b || blob), "image/jpeg", 0.3);
        });
        
        console.log(`[Gemini 图片压缩] 强制压缩: ${(compressedBlob.size / 1024 / 1024).toFixed(2)}MB，尺寸: ${canvas.width}x${canvas.height}`);
        return compressedBlob;
    } catch (error) {
        console.warn("[Gemini 图片压缩] 压缩失败，使用原始图片:", error);
        return blob;
    }
}

async function handleGeminiImageTask(config: Record<string, any>, input: Record<string, any>, references: Array<Record<string, any>>, model: string, connectionId: string) {
    const count = Math.max(1, Math.min(16, Math.trunc(Number(config.count) || 1)));
    const mask = input.mask && typeof input.mask === "object" ? input.mask as Record<string, any> : undefined;
    const request = async () => {
        const imageReferences = await Promise.all(references.slice(0, 16).map(async (reference) => {
            const blob = await resolveImageBlob(reference);
            if (!blob || !blob.size) throw new Error("参考图无法读取，请重新上传参考图");
            // 【修复】自动压缩图片到 10MB 以内（Gemini API 限制）
            const compressedBlob = await compressImageBlobIfNeeded(blob);
            return { dataUrl: await blobToDataUrl(compressedBlob), mimeType: compressedBlob.type || "image/jpeg" };
        }));
        const imageMask = mask ? await resolveImageBlob(mask) : null;
        if (mask && (!imageMask || !imageMask.size)) throw new Error("蒙版图片无法读取，请重新上传蒙版后再生成");
        // 【修复】蒙版图片也自动压缩到 10MB 以内
        const compressedMask = imageMask ? await compressImageBlobIfNeeded(imageMask) : null;
        const body = buildGeminiImageRequest(model, String(input.prompt || ""), imageReferences, compressedMask ? { dataUrl: await blobToDataUrl(compressedMask), mimeType: compressedMask.type || "image/jpeg" } : undefined, String(config.size || ""), String(config.quality || ""));
        const paths = [
            `/v1beta/models/${encodeURIComponent(model)}:generateContent`,
            `/v1/models/${encodeURIComponent(model)}:generateContent`,
        ];
        let response: Response | undefined;
        let lastError = "Gemini 图片生成失败";
        for (const path of paths) {
            response = await newApiFetch(path, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }, connectionId);
            if (response.ok) break;
            lastError = await readError(response, lastError);
            if (![404, 405].includes(response.status)) break;
        }
        if (!response?.ok) throw new Error(explainGeminiImageModelError(lastError, model));
        return parseGeminiImageDataUrls(await response.json());
    };
    const batches = await Promise.all(Array.from({ length: count }, request));
    const results = Array.from(new Set(batches.flat())).map((dataUrl) => ({ dataUrl, remoteUrl: undefined }));
    if (!results.length) throw new Error("Gemini 接口没有返回图片，请确认模型支持图片输出并允许 responseModalities=IMAGE");
    const taskId = `image-${nanoid()}`;
    taskConnections.set(taskId, connectionId);
    const normalized = { ...results[0], results };
    taskResults.set(taskId, normalized);
    await rememberStaticImageTask({ id: taskId, connectionId, baseUrl: getCreativeApiConnection(connectionId)?.baseUrl || getCreativeApiBaseUrl(), model: String(config.model || model), kind: references.length || mask ? "edit" : "generation", result: normalized, createdAt: Date.now() });
    return jsonResponse({ task: { id: taskId, kind: references.length || mask ? "edit" : "generation", model: config.model, status: "success", result: normalized } });
}


/**
 * 【修复】将 quality 值转换为 OpenAI API 支持的格式
 * OpenAI Images API 只支持 "standard" 和 "hd"，不支持 "4K"、"2K"、"高清" 等
 */
function normalizeOpenAiQuality(quality: unknown): string {
    const value = String(quality || "").toLowerCase().trim();
    if (!value || value === "auto") return "";
    if (/4k|4096|超高清|超清|hd|high/.test(value)) return "hd";
    if (/2k|2048|高清|standard|medium|1k|1024|标清|标准|low/.test(value)) return "standard";
    return value; // 其他值保持原样
}

function imageGenerationBody(model: string, input: Record<string, any>, config: Record<string, any>, size: string, responseFormat?: "url" | "b64_json") {
    return {
        model,
        prompt: input.prompt || "",
        ...(size && size !== "auto" ? { size } : {}),
        n: Number(config.count || 1),
        ...(normalizeOpenAiQuality(config.quality) ? { quality: normalizeOpenAiQuality(config.quality) } : {}),
        ...(responseFormat ? { response_format: responseFormat } : {}),
    };
}

async function imageEditFormData(config: Record<string, any>, input: Record<string, any>, references: Array<Record<string, any>>, size: string, responseFormat?: "url" | "b64_json", imageFieldName = openAiImageReferenceFieldName(references.length)) {
    const form = new FormData();
    form.set("model", modelName(String(config.model || "")));
    form.set("prompt", String(input.prompt || ""));
    if (size && size !== "auto") form.set("size", size);
    const normalizedQuality = normalizeOpenAiQuality(config.quality);
    if (normalizedQuality) form.set("quality", normalizedQuality);
    form.set("n", String(Number(config.count || 1)));
    if (responseFormat) form.set("response_format", responseFormat);
    for (const [index, reference] of references.slice(0, 16).entries()) {
        const blob = await resolveImageBlob(reference);
        if (!blob || !blob.size) throw new Error("参考图无法读取，请重新上传参考图后再生成");
        // 【修复】自动压缩图片到 10MB 以内（所有 API 都有类似限制）
        const compressedBlob = await compressImageBlobIfNeeded(blob);
        form.append(imageFieldName, compressedBlob, `reference-${index}.${imageExtensionForBlob(compressedBlob)}`);
    }
    if (input.mask?.dataUrl || input.mask?.url || input.mask?.serverUrl || input.mask?.remoteUrl || input.mask?.storageKey) {
        const blob = await resolveImageBlob(input.mask);
        if (!blob || !blob.size) throw new Error("蒙版图片无法读取，请重新上传蒙版后再生成");
        // 【修复】蒙版图片也自动压缩到 10MB 以内
        const compressedMask = await compressImageBlobIfNeeded(blob);
        form.set("mask", compressedMask, `mask.${imageExtensionForBlob(compressedMask)}`);
    }
    return form;
}

async function resolveImageBlob(reference: Record<string, any>): Promise<Blob | null> {
    const values = [reference.dataUrl, reference.serverUrl, reference.url, reference.remoteUrl].map((value) => String(value || "").trim()).filter(Boolean);
    for (const value of values) {
        if (value.startsWith("data:")) return dataUrlToBlob(value);
        if (/^\/api\/(?:reference-assets|generation-log-assets)\//i.test(value)) {
            const key = value.split("/").slice(3).map((part) => decodeURIComponent(part)).join("/");
            const media = await findLocalMedia(key);
            if (media) return dataUrlToBlob(media.dataUrl);
        }
        if (/^https?:\/\//i.test(value) || value.startsWith("/collab/media/")) {
            try {
                const response = await originalFetch(value, { cache: "no-store" });
                if (response.ok) return await response.blob();
            } catch {
                // Continue with another local or stable source.
            }
        }
    }
    if (reference.storageKey) {
        const media = await findLocalMedia(String(reference.storageKey));
        if (media) return dataUrlToBlob(media.dataUrl);
    }
    return null;
}

function imageExtensionForBlob(blob: Blob) {
    const subtype = (blob.type.split("/")[1] || "png").split(";")[0].toLowerCase();
    return subtype === "jpeg" ? "jpg" : /^[a-z0-9]+$/.test(subtype) ? subtype : "png";
}

async function rememberStaticImageTask(record: StaticImageTaskRecord) {
    await dbPut("image-tasks", record).catch((error) => console.warn("图片任务恢复信息保存失败", { taskId: record.id, error }));
}

function shouldRetryImageRequest(status: number, message: string) {
    // A missing route is a capability/configuration problem. Retrying the same
    // request with different multipart fields only duplicates work upstream.
    if ([404, 405].includes(status)) return false;
    if (![400, 404, 405, 415, 422].includes(status)) return false;
    return /response[_ -]?format|b64|base64|content[- ]type|multipart|form-?data|unsupported|not supported|invalid|images?\/(?:generations|edits)|endpoint|route|parse request body/i.test(message);
}

function explainImageModelError(message: string, model: string, status?: number) {
    if ([404, 405].includes(status || 0) || /(?:404|405)|not found|no route|route.*(?:missing|not)|endpoint.*(?:missing|not)/i.test(message)) {
        return `当前中转站没有开放图片编辑接口（/v1/images/edits），模型「${model}」无法处理参考图。请使用图片生成，或让中转站为该模型启用 OpenAI Images 编辑路由。`;
    }
    if (/only\s+imagen\s+models?\s+are\s+supported|not supported model for image generation/i.test(message)) {
        return `图片模型「${model}」不受当前中转站图片渠道支持：${message}。请在中转站为该模型配置图片渠道，或选择 Imagen 图片模型。`;
    }
    return message;
}

function explainGeminiImageModelError(message: string, model: string) {
    if (/only\s+imagen\s+models?\s+are\s+supported|not supported model for image generation/i.test(message)) {
        return `中转站没有开放 Gemini 图片模型「${model}」的 generateContent 路由，当前图片渠道只接受 Imagen。请改选模型列表中标为“Imagen / OpenAI Images”的模型，或让中转站为该 Gemini 模型启用 Gemini generateContent。`;
    }
    return message;
}

async function handleImageTaskById(id: string) {
    const persisted = await dbGet<StaticImageTaskRecord>("image-tasks", id).catch(() => undefined);
    if (persisted) {
        taskConnections.set(id, persisted.connectionId);
        if (persisted.result) {
            taskResults.set(id, persisted.result);
            return jsonResponse({ task: { id, status: "success", result: persisted.result } });
        }
    }
    const stored = taskResults.get(id);
    if (stored) return jsonResponse({ task: { id, status: "success", result: stored } });
    const upstream = await newApiFetch(persisted?.queryPath || `/v1/images/tasks/${encodeURIComponent(id)}`, {}, taskConnections.get(id), persisted?.baseUrl);
    if (!upstream.ok) return jsonResponse({ task: { id, status: "error", error: await readError(upstream, "图片任务查询失败") } }, upstream.status);
    const payload = await upstream.json() as Record<string, any>;
    const status = String(payload.status || payload.data?.status || "running").toLowerCase();
    const normalized = normalizeImageResponse(payload, persisted?.baseUrl || getCreativeApiBaseUrl());
    if (normalized.dataUrl) {
        taskResults.set(id, normalized);
        await rememberStaticImageTask({ ...(persisted || { id, connectionId: taskConnections.get(id) || "", kind: "generation", createdAt: Date.now() }), result: normalized });
    }
    return jsonResponse({ task: { id, status: ["succeeded", "success", "completed", "done"].includes(status) ? "success" : ["failed", "error", "cancelled"].includes(status) ? "error" : "running", result: normalized, error: payload.error?.message || payload.error } });
}

async function handleTextTask(init?: RequestInit) {
    const input = await readJson(init);
    const config = input.config || {};
    const connectionId = String(config.connectionId || "");
    const response = await chatCompletion(configForConnection(connectionId, String(config.model || "")), input.messages || []);
    if (!response.ok) return jsonResponse({ error: await readError(response, "文本生成失败") }, response.status);
    const payload = await response.json() as Record<string, any>;
    const taskId = `text-${nanoid()}`;
    taskConnections.set(taskId, connectionId);
    const content = textContent(payload.choices?.[0]?.message?.content) || textContent(payload.output_text);
    if (!content) return jsonResponse({ error: "文本接口没有返回内容，请检查模型是否支持文本对话" }, 502);
    taskResults.set(taskId, content);
    return jsonResponse({ task: { id: taskId, model: config.model, status: "success", result: { content } } });
}

async function handleTextTaskById(id: string) { return jsonResponse({ task: { id, status: "success", result: { content: taskResults.get(id) || "" } } }); }

async function handleVideoTask(init?: RequestInit) {
    const input = await readJson(init);
    const config = input.config || {};
    const model = String(config.model || "").trim().replace(/^.*::/, "");
    // /v1/videos 格式（OpenAI 兼容视频 API）作为所有中转站的通用格式，
    // 不绑定特定域名。只要模型名是视频模型就走这个格式。
    const modernVideoApi = /^(?:wan[-_.]?(?:2(?:\.1)?|3(?:\.0)?|3)?(?:[-_.](?:0|1080p|per[-_.]?second|per[-_.]?second[-_.]?1080))?|sd2[-_.]?5[-_.]?720p|sd2\.5[-_.]?720p|seedance[-_.]?\d(?:[-_.](?:pro|fast|mini))?|kling[-_.]?\d|sora[-_.]?\d|veo[-_.]?\d|hailuo[-_.]?\d|runway[-_.]?\d|luma[-_.]?\d|vidu[-_.]?\d|cogvideo[-_.]?\d|mochi[-_.]?\d|ltx[-_.]?\d|hunyuanvideo[-_.]?\d|pixverse[-_.]?\d|pika[-_.]?\d|gemini[-_.]?omni[-_.]?\d|gen[-_.]?\d)$/i.test(model) || String(config.protocol || "").toLowerCase() === "jui87";
    const references = Array.isArray(input.references) ? input.references as Array<Record<string, unknown>> : [];
    const urls = (type: string) => references.filter((item) => item.type === type).map((item) => String(item.url || item.dataUrl || "")).filter(Boolean);
    // Sub2 accepts data URLs for video references and materializes them on
    // its own server under /app/data/public-media. Keep local data URLs in
    // the request instead of rejecting them in the browser; this avoids
    // requiring a separate /public-media upload endpoint.
    const seconds = Number(config.videoSeconds || 5);
    const prompt = limitStaticVideoPrompt(String(input.prompt || ""));
    const aspectRatio = typeof config.aspectRatio === "string" && config.aspectRatio.trim() ? config.aspectRatio.trim() : (typeof config.size === "string" && /^\d+:\d+$/.test(config.size.trim()) ? config.size.trim() : "");
    const isSeedance = model.toLowerCase().includes("seedance");
    const resolution = typeof config.videoResolution === "string" && config.videoResolution.trim() ? config.videoResolution.trim() : "720p";
    const hasReferences = urls("image").length > 0 || urls("video").length > 0 || urls("audio").length > 0;
    const body = modernVideoApi
        ? {
              model,
              prompt,
              seconds: Math.min(30, Math.max(1, Math.trunc(seconds) || 5)),
              resolution,
              ...(aspectRatio ? { aspect_ratio: aspectRatio } : {}),
              ...(hasReferences && isSeedance ? { mode: "reference-to-video" } : {}),
              ...(config.videoGenerateAudio === "false" ? { sound_effects: false } : {}),
              ...(urls("image").length ? { reference_images: urls("image").slice(0, isSeedance ? 9 : 2) } : {}),
              ...(urls("video").length ? { reference_videos: urls("video").slice(0, 9) } : {}),
              ...(urls("audio").length ? { reference_audios: urls("audio").slice(0, 9) } : {}),
          }
        : { model, prompt, size: config.size, seconds, generate_audio: config.videoGenerateAudio !== "false" };
    const connectionId = String(config.connectionId || "");
    const response = await videoApiFetch(modernVideoApi ? "/v1/videos" : "/v1/videos/generations", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }, connectionId);
    if (!response.ok) return jsonResponse({ error: await readError(response, "视频任务创建失败") }, response.status === 401 ? 502 : response.status);
    const payload = await response.json() as Record<string, any>;
    const id = String(payload.id || payload.task_id || payload.data?.id || `video-${nanoid()}`);
    const protocol = modernVideoApi ? "jui87" : "legacy";
    videoTaskProtocols.set(id, protocol);
    taskConnections.set(id, connectionId);
    taskRequests.set(id, Promise.resolve(payload));
    // The page can be unloaded while an upstream video task is still running.
    // Keep the query route and connection identity outside the in-memory maps
    // so reopening the canvas can continue polling the original task.
    await dbPut("video-tasks", {
        id,
        connectionId,
        protocol,
        baseUrl: getCreativeApiConnection(connectionId)?.baseUrl || getCreativeApiBaseUrl(),
        model: String(config.model || ""),
        createdAt: Date.now(),
    } satisfies StaticVideoTaskRecord).catch((error) => {
        console.warn("视频任务恢复信息保存失败", { taskId: id, error });
    });
    return jsonResponse({ task: { id, model: config.model, durationSeconds: Number(config.videoSeconds || 5) } });
}

const STATIC_VIDEO_PROMPT_LIMIT = 8500;

function limitStaticVideoPrompt(value: string) {
    if (value.length <= STATIC_VIDEO_PROMPT_LIMIT) return value;
    const suffix = "\n[视频提示词已截断，保留前文以符合中转站 10000 字符限制]";
    return `${value.slice(0, STATIC_VIDEO_PROMPT_LIMIT - suffix.length)}${suffix}`;
}

async function handleVideoTaskById(id: string) {
    const stored = await dbGet<StaticVideoTaskRecord>("video-tasks", id).catch(() => undefined);
    if (stored?.result) return jsonResponse({ task: { id, status: "success", result: stored.result } });
    const protocol = videoTaskProtocols.get(id) || stored?.protocol || (/(?:api\.jui87\.com|sub\.jui87\.com|808relay)/i.test(stored?.baseUrl || getCreativeApiBaseUrl()) ? "jui87" : "legacy");
    const connectionId = taskConnections.get(id) || stored?.connectionId || "";
    videoTaskProtocols.set(id, protocol);
    taskConnections.set(id, connectionId);
    const response = await videoApiFetch(protocol === "jui87" ? `/v1/videos/${encodeURIComponent(id)}` : `/v1/videos/generations/${encodeURIComponent(id)}`, {}, connectionId, stored?.baseUrl);
    if (!response.ok) return jsonResponse({ task: { id, status: "error", error: await readError(response, "视频任务查询失败") } }, response.status === 401 ? 502 : response.status);
    const payload = await response.json() as Record<string, any>;
    const status = String(payload.status || payload.data?.status || "running").toLowerCase();
    const isSuccess = ["succeeded", "success", "completed", "done"].includes(status);
    let url = payload.url || payload.result_url || payload.video_url || payload.data?.url || payload.data?.video_url || payload.data?.result_url || payload.video_urls?.[0] || payload.data?.video_urls?.[0] || payload.metadata?.url || payload.metadata?.result_url;
    // 当任务成功时，总是通过带鉴权的 /content 端点下载视频并转成 data URL，
    // 避免返回需要鉴权的端点 URL 导致前端 storeGeneratedVideo 下载时 401。
    if (isSuccess) {
        try {
            const content = await videoApiFetch(`/v1/videos/${encodeURIComponent(id)}/content`, {}, connectionId, stored?.baseUrl);
            if (content.ok) {
                const blob = await content.blob();
                if (blob.size) url = await blobToDataUrl(blob);
            }
        } catch (contentError) {
            console.warn("视频内容下载失败，回退使用上游返回的 URL", { taskId: id, contentError });
        }
    }
    const result = url ? { url } : undefined;
    if (result && ["succeeded", "success", "completed", "done"].includes(status)) {
        await dbPut("video-tasks", { ...(stored || { id, connectionId, protocol, createdAt: Date.now() }), result }).catch((error) => console.warn("视频结果保存失败", { taskId: id, error }));
    }
    return jsonResponse({ task: { id, status: ["succeeded", "success", "completed", "done"].includes(status) ? "success" : ["failed", "error", "cancelled"].includes(status) ? "error" : "running", result, error: payload.error?.message || payload.error } });
}

async function handleAgent(path: string, search: URLSearchParams, init?: RequestInit) {
    const parts = path.split("/").filter(Boolean);
    if (parts[2] === "runs" && parts.length === 3) {
        if ((init?.method || "GET") === "GET") {
            const requestedLimit = Number(search.get("limit"));
            const limit = Number.isSafeInteger(requestedLimit) && requestedLimit > 0 ? Math.min(50, requestedLimit) : 50;
            const surface = search.get("surface")?.trim();
            const projectId = search.get("projectId")?.trim();
            const conversationId = search.get("conversationId")?.trim();
            const activeOnly = search.get("status") === "active";
            const storedRuns = await dbList<Record<string, any>>("agent-runs");
            const runs = storedRuns
                .filter((run) => (!surface || run.surface === surface) && (!projectId || run.projectId === projectId) && (!conversationId || run.conversationId === conversationId))
                .filter((run) => !activeOnly || ["planning", "running", "paused"].includes(run.status))
                .sort((left, right) => Number(right.updatedAt || right.createdAt || 0) - Number(left.updatedAt || left.createdAt || 0))
                .slice(0, limit);
            runs.forEach((run) => agentRuns.set(String(run.id), run));
            return jsonResponse({ code: 0, data: { runs }, msg: "OK" });
        }
        return handleAgentCreate(init);
    }
    if (parts[2] === "runs" && parts[3]) {
        const runId = decodeURIComponent(parts[3]);
        const run = agentRuns.get(runId) || await dbGet<Record<string, any>>("agent-runs", runId);
        if (!run) return jsonResponse({ code: 404, data: null, msg: "Agent 任务不存在" }, 404);
        agentRuns.set(runId, run);
        if (parts[4] === "tasks" && parts[5] && parts[6] === "retry" && (init?.method || "GET") === "POST") {
            const task = run.tasks.find((item: Record<string, any>) => item.id === parts[5]);
            if (!task) return jsonResponse({ code: 404, data: null, msg: "Agent 子任务不存在" }, 404);
            if (!["failed", "cancelled"].includes(task.status)) return jsonResponse({ code: 409, data: null, msg: "只有失败或已取消任务可以重试" }, 409);
            task.status = "running";
            delete task.error;
            run.status = "running";
            run.updatedAt = Date.now();
            await dbPut("agent-runs", run);
            return jsonResponse({ code: 0, data: { run }, msg: "OK" });
        }
        if (parts.length >= 6 && parts[4] === "tasks") return jsonResponse({ code: 0, data: { run }, msg: "OK" });
        if (parts.length >= 5 && (init?.method || "GET") === "POST") {
            const action = parts[4];
            if (action === "cancel") run.status = "cancelled";
            if (action === "pause") run.status = "paused";
            if (action === "resume") run.status = "running";
            if (action === "retry") {
                run.status = "running";
                const task = run.tasks.find((item: Record<string, any>) => item.id === parts[6]);
                if (task) task.status = "running";
            }
            run.updatedAt = Date.now();
            await dbPut("agent-runs", run);
            return jsonResponse({ code: 0, data: { run }, msg: "OK" });
        }
        return jsonResponse({ code: 0, data: { run }, msg: "OK" });
    }
    return jsonResponse({ code: 404, data: null, msg: "Agent 接口不存在" }, 404);
}

async function handleAgentCreate(init?: RequestInit) {
    const input = await readJson(init);
    const clientRequestId = String(input.clientRequestId || "").trim();
    if (clientRequestId) {
        const persisted = (await dbList<Record<string, any>>("agent-runs")).find((run) => run.clientRequestId === clientRequestId);
        if (persisted) {
            agentRuns.set(String(persisted.id), persisted);
            return jsonResponse({ code: 0, data: { run: persisted, created: false }, msg: "Agent 任务已存在" });
        }
        const pending = staticAgentRequestPromises.get(clientRequestId);
        if (pending) {
            const response = await pending;
            return response.clone();
        }
        const request = handleAgentCreateOnce(input, init?.signal || undefined);
        staticAgentRequestPromises.set(clientRequestId, request);
        try {
            const response = await request;
            return response.clone();
        } finally {
            if (staticAgentRequestPromises.get(clientRequestId) === request) staticAgentRequestPromises.delete(clientRequestId);
        }
    }
    return handleAgentCreateOnce(input, init?.signal || undefined);
}

async function handleAgentCreateOnce(input: Record<string, any>, signal?: AbortSignal) {
    const requestedSurface = String(input.surface || "").trim();
    const clientRequestId = String(input.clientRequestId || "").trim();
    const promptText = String(input.prompt || "").trim();
    if (!clientRequestId) return jsonResponse({ code: 400, data: null, msg: "请求标识不能为空" }, 400);
    if (!promptText) return jsonResponse({ code: 400, data: null, msg: "创作需求不能为空" }, 400);
    if (requestedSurface !== "canvas") return jsonResponse({ code: 400, data: null, msg: "创作入口不正确" }, 400);
    const surface = requestedSurface;
    if (!String(input.projectId || "").trim()) return jsonResponse({ code: 400, data: null, msg: "画布标识不能为空" }, 400);
    const runId = `agent-${nanoid()}`;
    const requestedModels: string[] = Array.from(new Set(Array.isArray(input.modelIds) ? (input.modelIds as unknown[]).map((item) => String(item).trim()).filter(Boolean) : [])).slice(0, 6);
    const preferred = requestedModels.find((item) => inferModelCapability(modelName(item)) === "text") || findCachedTextModel();
    const model = modelName(preferred);
    const connectionId = connectionIdFromModel(preferred) || getActiveCreativeApiConnection()?.id;
    if (!model) return jsonResponse({ code: 400, data: null, msg: "请先在设置中配置可用的文本或推理模型" }, 400);
    const selectedSkillIds = Array.from(new Set(Array.isArray(input.skillIds) ? input.skillIds.map((item: unknown) => String(item).trim()).filter(Boolean) : [])).slice(0, 6);
    const selectedSkills = [...BUILTIN_AGENT_SKILLS, ...(await dbList<StaticAgentSkill>("skills"))].filter((skill) => selectedSkillIds.includes(skill.id) && skill.workspaces.includes(surface));
    const selectedSkillRules = await Promise.all(selectedSkills.map(async (skill) => {
        if (skill.source !== "server") return { skill, instructions: skill.instructions };
        try {
            return { skill, instructions: await fetchBuiltinSkillInstructions(skill.id) };
        } catch {
            return { skill, instructions: skill.instructions };
        }
    }));
    const skillInstructions = selectedSkillRules.length
        ? `\n\n【多 Skill 协同执行铁律】\n用户启用了 ${selectedSkillRules.length} 个 Skill，你必须：\n1. 先深度理解用户的真实意图和核心需求，不要机械地执行所有 Skill 的所有规则；\n2. 根据用户意图，从各个 Skill 中提取最相关、最有价值的规则进行组合执行；\n3. 如果多个 Skill 的规则有冲突，以用户的明确需求为准，选择最符合用户意图的方案；\n4. 不要为了执行 Skill 规则而生成用户不需要的内容，只创建确实有帮助的节点；\n5. 生成的图片数量、比例、质量必须严格遵循用户在输入中明确指定的参数（如"9:16"、"6张"、"4K"等）。\n\n【生图提示词铁律】每个 image 节点的 metadata.prompt 必须是详细的、完整的生图提示词，包含：产品描述+构图方式+配色方案+背景场景+光影效果+画质参数+卖点标签位置，绝对不能只写一句话！必须把 Skill 中的视觉策略、构图、配色、文案等规则融入到每个生图提示词中！\n\n用户启用的 Skill 规则（按需提取执行，不要全部机械执行）：\n${selectedSkillRules.map(({ skill, instructions }) => `【${skill.name}】\n${instructions.slice(0, 5000)}`).join("\n\n").slice(0, 25000)}`
        : "";
    const system = `你是创作画布 Agent。根据用户需求返回 JSON，不要返回 Markdown。字段：reply:string，ops:数组。ops 允许使用 add_node、connect_nodes、update_node、delete_node、delete_connections、clear_canvas、select_nodes、set_viewport、run_generation。删除或清空画布时必须实际返回 delete_node、delete_connections 或 clear_canvas，不能只在 reply 里说明已删除。delete_node 的 id/ids 必须使用当前画布快照中的节点 id；删除用户当前选中的节点时使用 ids:["selected"]；清空全部节点时使用 clear_canvas。add_node 的 nodeType 只能是 brief、text、image、video、audio、config、task、brand-kit、panorama，position 使用整数 x/y，metadata 可放 content、prompt、status、size、quality、count。需要实际生成图片、视频、音频或文本时，必须创建对应 nodeType 的节点并给出 metadata.prompt；不要只在 reply 里声称完成。对 image、video、audio 节点必须让系统执行生成操作。只创建确实有帮助的节点，回复简洁。【用户参数铁律】用户在输入中明确指定的图片数量（如"6张"）、比例（如"9:16"、"1:1"）、质量（如"4K"、"2K"、"高清"）必须严格遵守，并写入对应 image 节点的 metadata.size、metadata.quality、metadata.count，不得擅自更改或忽略。${skillInstructions}`;
    const selectedAssets = Array.isArray(input.assetIds)
        ? (await dbList<Record<string, any>>("creative-assets")).filter((asset) => input.assetIds.map(String).includes(String(asset.id)))
        : [];
    const referenceImages = [
        ...(Array.isArray(input.snapshot?.referenceImages) ? input.snapshot.referenceImages : []),
        ...selectedAssets.map((asset) => ({ id: asset.id, dataUrl: asset.dataUrl || asset.serverUrl || asset.remoteUrl, storageKey: asset.storageKey })),
    ].filter((reference, index, list) => list.findIndex((item) => String(item.id || item.dataUrl || "") === String(reference.id || reference.dataUrl || "")) === index);
    const context = { ...input.snapshot, referenceImages: undefined };
    const parts: Array<Record<string, unknown>> = [{ type: "text", text: `${promptText}\n\n当前项目上下文：${JSON.stringify(context).slice(0, 24000)}` }];
    for (const reference of referenceImages) {
        const blob = await resolveImageBlob(reference);
        if (!blob) throw new Error("Agent 参考图无法读取，请重新选择图片");
        // 【修复】自动压缩图片到 10MB 以内（所有 API 都有类似限制）
        const compressedBlob = await compressImageBlobIfNeeded(blob);
        parts.push({ type: "image_url", image_url: { url: await blobToDataUrl(compressedBlob) } });
    }
    const contract = '\n输出结构优先于 Skill 的排版规则。操作示例：{"reply":"已准备生成任务","ops":[{"type":"add_node","nodeType":"image","metadata":{"prompt":"完整写真提示词","count":1}}]}。每张图片一个 image 节点。文字内容使用 text 节点的 metadata.content。不要把 nodeType 放在 type 字段。只输出待执行计划，图片尚未生成，不得声称已生成或已检查图片。';
    const messages: unknown[] = [{ role: "system", content: system + contract }, { role: "user", content: parts }];
    let raw: unknown = "";
    let result: Record<string, any> = {};
    for (let attempt = 0; attempt < 2; attempt++) {
        // 使用流式请求，避免 Cloudflare 等代理的超时限制（上游一边生成一边返回）
        const streamResult = await streamChatCompletion(configForConnection(connectionId, model), messages, { json: true, reasoning: isReasoningModel(model), signal });
        if (!streamResult.ok) return jsonResponse({ code: streamResult.status, data: null, msg: `Agent 调用失败：${streamResult.error || "未知错误"}` }, streamResult.status);
        raw = streamResult.content;
        let invalid = "";
        try {
            result = parseAgentPlan(raw);
            if (surface === "canvas") invalid = canvasPlanError(result, promptText, referenceImages.length > 0);
        } catch { invalid = "模型没有返回有效 JSON 操作计划"; }
        if (!invalid) break;
        if (attempt === 1) return jsonResponse({ code: 422, data: null, msg: `Agent 计划校验失败：${invalid}。未执行画布操作，请重试或更换文本模型。` }, 422);
        messages.push({ role: "assistant", content: typeof raw === "string" ? raw : JSON.stringify(raw) }, { role: "user", content: `修正本次 JSON 计划：${invalid}。遵守操作示例，返回完整 JSON。` });
    }
    const selectedNodeIds = Array.isArray(input.snapshot?.selectedNodeIds) ? input.snapshot.selectedNodeIds.map((id: unknown) => String(id)) : [];
    const selectedNodeSet = new Set(selectedNodeIds);
    const referenceNodeIds = Array.isArray(input.snapshot?.nodes)
        ? input.snapshot.nodes
              .filter((node: any) => selectedNodeSet.has(String(node?.id || "")) && ["image", "video", "panorama"].includes(String(node?.type || "")))
              .map((node: any) => String(node?.id || ""))
              .filter(Boolean)
        : [];
    const ops = surface === "canvas" ? buildStaticCanvasAgentOps(result.ops, { runId, requestedModels, prompt: promptText, preferences: input.preferences, selectedNodeIds, referenceNodeIds, allNodeIds: Array.isArray(input.snapshot?.nodes) ? input.snapshot.nodes.map((node: any) => String(node?.id || "")).filter(Boolean) : [] }) : [];
    const mediaCount = ops.filter((op: Record<string, any>) => op.type === "run_generation").length;
    const taskOps = ops.filter((op: Record<string, any>) => op.type === "add_node" && op.metadata?.agentTaskId);
    const reply = mediaCount ? "生成计划已就绪，正在执行画布任务。" : String(result.reply || "画布操作计划已就绪");
    const skillNames = selectedSkills.map((skill) => skill.name);
    const skillNotice = skillNames.length ? `\n\n已应用 Skill 规则：${skillNames.join("、")}` : "";
    const now = Date.now();
    if (signal?.aborted) throw new DOMException("请求已取消", "AbortError");
    const run = { id: runId, clientRequestId, conversationId: String(input.conversationId || `conversation-${nanoid()}`), inputMessageId: `message-${nanoid()}`, assistantMessageId: `message-${nanoid()}`, status: "completed", surface, projectId: input.projectId, prompt: promptText, requestedModelIds: requestedModels, referencedAssetIds: Array.isArray(input.assetIds) ? Array.from(new Set(input.assetIds.map(String))) : [], selectedSkillIds, selectedSkillNames: skillNames, assetIds: [], tasks: taskOps.map((op: Record<string, any>) => ({ id: op.metadata.agentTaskId, title: String(op.title || "画布任务"), type: op.metadata.agentTaskType || "text", model: op.metadata.model || model, status: mediaCount ? "ready" : "completed" })), reply: `${mediaCount ? `${reply}\n\n已创建 ${mediaCount} 个生成任务，结果会直接回写到画布节点。` : reply}${skillNotice}`, canvasOps: surface === "canvas" ? ops : [], createdAt: now, updatedAt: now };
    agentRuns.set(runId, run);
    await dbPut("agent-runs", run);
    const conversationId = run.conversationId;
    const conversation = (await dbGet<Record<string, any>>("creative-conversations", conversationId)) || {
        id: conversationId,
        userId: "static-local",
        surface,
        source: surface,
        projectId: input.projectId,
        title: String(input.prompt || "新对话").slice(0, 48),
        status: "active",
        contextSummary: "",
        contextSummaryThroughSequence: 0,
        createdAt: now,
        updatedAt: now,
        lastMessageAt: now,
    };
    await dbPut("creative-conversations", { ...conversation, surface, projectId: input.projectId, updatedAt: now, lastMessageAt: now });
    await dbPut("creative-messages", {
        id: run.inputMessageId,
        conversationId,
        sequence: Number(conversation.lastSequence || 0) + 1,
        role: "user",
        status: "completed",
        content: String(input.prompt || ""),
        runId,
        metadata: { assetIds: Array.isArray(input.assetIds) ? input.assetIds : [] },
        createdAt: now,
        updatedAt: now,
    });
    await dbPut("creative-messages", {
        id: run.assistantMessageId,
        conversationId,
        sequence: Number(conversation.lastSequence || 0) + 2,
        role: "assistant",
        status: "completed",
        content: String(run.reply || "Agent 已完成"),
        runId,
        metadata: {},
        createdAt: now,
        updatedAt: now,
    });
    await dbPut("creative-conversations", { ...conversation, surface, projectId: input.projectId, lastSequence: Number(conversation.lastSequence || 0) + 2, updatedAt: now, lastMessageAt: now });
    return jsonResponse({ code: 0, data: { run, created: true }, msg: "Agent 任务已完成" });
}


function buildStaticCanvasAgentOps(rawValue: unknown, context: { runId: string; requestedModels: string[]; prompt: string; preferences?: Record<string, any>; selectedNodeIds: string[]; referenceNodeIds: string[]; allNodeIds: string[] }) {
    const rawOps = Array.isArray(rawValue) ? rawValue.filter((item): item is Record<string, any> => Boolean(item) && typeof item === "object") : [];
    const prompt = context.prompt.trim();
    const lower = prompt.toLowerCase();
    const isClearRequest = /^(?:请|帮我)?\s*(?:清空画布|删除所有节点|clear canvas)[。！!]?$/i.test(lower);
    const isSelectedDeleteRequest = /^(?:请|帮我)?\s*(?:删除|移除)(?:选中|当前选中)的?节点[。！!]?$/i.test(lower) && context.selectedNodeIds.length > 0;
    const hasClearOperation = rawOps.some((op) => op.type === "clear_canvas");
    const hasDeleteOperation = rawOps.some((op) => op.type === "delete_node");
    if (isClearRequest && !hasClearOperation) {
        rawOps.length = 0;
        rawOps.push({ type: "clear_canvas" });
    } else if (isSelectedDeleteRequest && !hasDeleteOperation) {
        rawOps.length = 0;
        rawOps.push({ type: "delete_node", ids: ["selected"] });
    }
    const idMap = new Map<string, string>();
    const operations: Record<string, any>[] = [];
    const generationOps: Record<string, any>[] = [];
    let addIndex = 0;
    rawOps.forEach((op) => {
        if (op.type !== "add_node") return;
        const nodeType = ["brief", "text", "image", "video", "audio", "config", "task", "brand-kit", "panorama"].includes(String(op.nodeType)) ? String(op.nodeType) : "text";
        const id = `agent-node-${context.runId}-${addIndex}`;
        if (op.id) idMap.set(String(op.id), id);
        const mode = nodeType === "panorama" ? "image" : nodeType === "image" || nodeType === "video" || nodeType === "audio" || nodeType === "text" ? nodeType : undefined;
        const metadata = { ...(op.metadata || {}) } as Record<string, any>;
        const prompt = String(metadata.prompt || metadata.sourcePrompt || op.prompt || (nodeType === "text" ? metadata.content : context.prompt) || context.prompt).trim();
        if (mode) {
            const model = pickStaticAgentModel(context.requestedModels, mode);
            const preferences = context.preferences?.[mode];
            const preferenceSize = normalizeImageSizeValue(preferences?.size);
            const metadataSize = normalizeImageSizeValue(metadata.size);
            const promptSize = extractImageSizeFromPrompt(prompt) || extractImageSizeFromPrompt(context.prompt);
            const agentSize = preferenceSize && preferenceSize !== "auto" ? preferenceSize : metadataSize && metadataSize !== "auto" ? metadataSize : promptSize;

            // 【修复】quality 的优先级：preferences.quality > metadata.quality > prompt 中提取的 quality
            // 之前只从 preferences 中获取 quality，导致 Agent 在 metadata 中设置的 quality（如 4K）不会被传递
            const extractQualityFromPrompt = (text: string): string => {
                const lower = text.toLowerCase();
                if (/4k|4096|超高清|超清/.test(lower)) return "high";
                if (/2k|2048|高清/.test(lower)) return "medium";
                if (/1k|1024|标清|标准/.test(lower)) return "low";
                return "";
            };
            const preferenceQuality = String(preferences?.quality || "").trim();
            const metadataQuality = String(metadata.quality || "").trim();
            const promptQuality = extractQualityFromPrompt(prompt) || extractQualityFromPrompt(context.prompt);
            const agentQuality = preferenceQuality && preferenceQuality !== "auto" ? preferenceQuality : metadataQuality && metadataQuality !== "auto" ? metadataQuality : promptQuality;

            Object.assign(metadata, {
                agentRunId: context.runId,
                agentTaskId: `agent-task-${context.runId}-${addIndex}`,
                agentTaskStatus: metadata.content && mode === "text" ? "completed" : "running",
                agentTaskType: mode,
                agentTaskAttempts: 1,
                prompt,
                generationMode: mode,
                model: model || undefined,
                status: metadata.content && mode === "text" ? "success" : "loading",
                ...(agentSize || preferences?.size ? { size: String(agentSize || preferences?.size) } : {}),
                ...(agentQuality ? { quality: String(agentQuality) } : {}),
                ...(mode === "image" ? { count: Math.max(1, Number(metadata.count) || 1) } : preferences?.count ? { count: Number(preferences.count) } : {}),
                ...(preferences?.seconds ? { seconds: String(preferences.seconds) } : {}),
                ...(preferences?.generateAudio !== undefined ? { generateAudio: String(Boolean(preferences.generateAudio)) } : {}),
            });
        } else {
            Object.assign(metadata, { agentRunId: context.runId, prompt: prompt || context.prompt });
        }
        operations.push({ type: "add_node", id, nodeType, title: String(op.title || (mode ? `Agent ${mode === "image" ? "图片" : mode === "video" ? "视频" : mode === "audio" ? "音频" : "文本"}` : "Agent 节点")), position: { x: Number(op.position?.x ?? op.x ?? addIndex * 420), y: Number(op.position?.y ?? op.y ?? 80) }, ...(op.width ? { width: Number(op.width) } : {}), ...(op.height ? { height: Number(op.height) } : {}), metadata });
        if ((mode === "image" || mode === "video") && context.referenceNodeIds.length) {
            context.referenceNodeIds.forEach((referenceNodeId) => operations.push({ type: "connect_nodes", fromNodeId: referenceNodeId, toNodeId: id }));
        }
        if (mode && !(mode === "text" && metadata.content)) generationOps.push({ type: "run_generation", nodeId: id, mode, prompt });
        addIndex += 1;
    });
    rawOps.forEach((op) => {
        if (op.type === "clear_canvas") {
            operations.push({ type: "clear_canvas" });
        } else if (op.type === "delete_node") {
            const rawIds = Array.isArray(op.ids) ? op.ids.map((id: unknown) => String(id)) : op.id ? [String(op.id)] : [];
            const ids = rawIds.some((id: string) => ["selected", "current", "当前"].includes(id.toLowerCase())) ? context.selectedNodeIds : rawIds.some((id: string) => ["all", "*", "全部"].includes(id.toLowerCase())) ? context.allNodeIds : rawIds;
            operations.push({ type: "delete_node", ...(ids.length ? { ids } : {}), ...(op.nodeType ? { nodeType: op.nodeType } : {}) });
        } else if (op.type === "delete_connections") {
            operations.push({ type: "delete_connections", ...(op.all ? { all: true } : {}), ...(op.id ? { id: String(op.id) } : {}), ...(Array.isArray(op.ids) ? { ids: op.ids.map((id: unknown) => String(id)) } : {}) });
        } else if (op.type === "select_nodes") {
            const ids = Array.isArray(op.ids) && op.ids.some((id: unknown) => ["selected", "current"].includes(String(id).toLowerCase())) ? context.selectedNodeIds : Array.isArray(op.ids) ? op.ids.map((id: unknown) => String(id)) : [];
            operations.push({ type: "select_nodes", ids });
        } else if (op.type === "set_viewport" && op.viewport) {
            operations.push({ type: "set_viewport", viewport: op.viewport });
        } else if (op.type === "connect_nodes") {
            const fromNodeId = idMap.get(String(op.fromNodeId)) || String(op.fromNodeId || "");
            const toNodeId = idMap.get(String(op.toNodeId)) || String(op.toNodeId || "");
            if (fromNodeId && toNodeId) operations.push({ type: "connect_nodes", id: op.id || undefined, fromNodeId, toNodeId });
        } else if (op.type === "update_node" && op.id) {
            operations.push({ type: "update_node", id: idMap.get(String(op.id)) || String(op.id), patch: op.patch, metadata: op.metadata });
        } else if (op.type === "run_generation" && context.allNodeIds.includes(String(op.nodeId))) {
            generationOps.push({ type: "run_generation", nodeId: String(op.nodeId), mode: op.mode, prompt: op.prompt });
        }
    });
    return [...operations, ...generationOps];
}

function pickStaticAgentModel(requestedModels: string[], capability: "text" | "image" | "video" | "audio") {
    const requested = requestedModels.find((item) => inferModelCapability(modelName(item)) === capability);
    return requested || findCachedModel(capability);
}

function findCachedModel(capability: "text" | "image" | "video" | "audio") {
    // 优先使用当前激活的中转站的模型
    const activeConnection = getActiveCreativeApiConnection();
    if (activeConnection) {
        const activeModels = modelCatalogCache.get(activeConnection.id);
        if (activeModels) {
            const model = activeModels.find((item) => (item.capability || inferModelCapability(item.id)) === capability);
            if (model) return `${activeConnection.id}::${model.id}`;
        }
    }
    // 然后遍历所有中转站的缓存
    for (const [connectionId, models] of modelCatalogCache) {
        const model = models.find((item) => (item.capability || inferModelCapability(item.id)) === capability);
        if (model) return `${connectionId}::${model.id}`;
    }
    return "";
}

async function handleAgentPromptOptimization(init?: RequestInit) {
    const input = await readJson(init);
    const modelEntry = findCachedTextModel() || Array.from(modelCatalogCache.values()).flat()[0]?.id || "";
    const model = modelName(modelEntry);
    const connectionId = connectionIdFromModel(modelEntry) || getActiveCreativeApiConnection()?.id;
    if (!model) return jsonResponse({ code: 400, data: null, msg: "请先配置文本或推理模型" }, 400);
    const response = await chatCompletion(configForConnection(String(connectionId || ""), model), [{ role: "system", content: '优化用户提示词，保留原意，只返回 JSON：{"prompt":"优化后的提示词"}' }, { role: "user", content: String(input.prompt || "") }], { json: true, reasoning: isReasoningModel(model) });
    if (!response.ok) return jsonResponse({ code: response.status, data: null, msg: await readError(response, "提示词优化失败") }, response.status);
    const payload = await response.json() as Record<string, any>;
    const raw = textContent(payload.choices?.[0]?.message?.content) || textContent(payload.output_text) || String(input.prompt || "");
    let prompt = String(raw);
    try { prompt = String(parseJsonText(raw).prompt || prompt); } catch { /* keep raw text */ }
    return jsonResponse({ code: 0, data: { prompt: prompt.trim() }, msg: "OK" });
}

function findCachedTextModel() {
    return findCachedModel("text");
}

function modelName(value: string) { return normalizeImageModelName(value); }
function connectionIdFromModel(value: string) { const index = value.indexOf("::"); return index > 0 ? value.slice(0, index) : ""; }
function isReasoningModel(model: string) { return /(?:reason|think|r1|qwq|o1|o3|o4)/i.test(model); }

async function handleCreativeConversations(path: string, search: URLSearchParams, init?: RequestInit) {
    const parts = path.split("/").filter(Boolean);
    if (parts.length === 3) {
        if ((init?.method || "GET") === "GET") {
            const surface = search.get("surface")?.trim();
            const projectId = search.get("projectId")?.trim();
            const offset = Math.max(0, Number(search.get("offset")) || 0);
            const limit = Math.min(100, Math.max(1, Number(search.get("limit")) || 50));
            const conversations = (await dbList<Record<string, any>>("creative-conversations"))
                .filter((item) => (!surface || item.surface === surface) && (!projectId || item.projectId === projectId) && item.status !== "archived")
                .sort((left, right) => Number(right.lastMessageAt || right.updatedAt || 0) - Number(left.lastMessageAt || left.updatedAt || 0));
            return jsonResponse({ code: 0, data: { conversations: conversations.slice(offset, offset + limit), hasMore: offset + limit < conversations.length }, msg: "OK" });
        }
        if ((init?.method || "GET") === "DELETE") {
            const input = await readJson(init);
            const ids: string[] = Array.from(new Set<string>(Array.isArray(input.ids) ? input.ids.map((item: unknown) => String(item)).filter(Boolean) : []));
            for (const id of ids) await deleteStaticCreativeConversation(id);
            return jsonResponse({ code: 0, data: { deleted: ids.length }, msg: "OK" });
        }
        const input = await readJson(init);
        const id = `conversation-${nanoid()}`;
        const conversation = { id, userId: "static-local", surface: input.surface || "canvas", source: input.source || input.surface || "canvas", projectId: input.projectId, title: input.title || "新对话", status: "active", contextSummary: "", contextSummaryThroughSequence: 0, createdAt: Date.now(), updatedAt: Date.now(), lastMessageAt: Date.now() };
        creativeConversations.set(id, conversation);
        await dbPut("creative-conversations", conversation);
        return jsonResponse({ code: 0, data: { conversation }, msg: "OK" });
    }
    const id = decodeURIComponent(parts[3] || "");
    const conversation = creativeConversations.get(id) || await dbGet<Record<string, any>>("creative-conversations", id) || { id, userId: "static-local", surface: "canvas", source: "canvas", title: "创作对话", status: "active", contextSummary: "", contextSummaryThroughSequence: 0, createdAt: Date.now(), updatedAt: Date.now(), lastMessageAt: Date.now() };
    creativeConversations.set(id, conversation);
    if (parts.at(-1) === "messages") {
        const messages = (await dbList<Record<string, any>>("creative-messages"))
            .filter((item) => item.conversationId === id)
            .sort((left, right) => Number(left.sequence || 0) - Number(right.sequence || 0));
        return jsonResponse({ code: 0, data: { messages }, msg: "OK" });
    }
    if (parts.at(-1) === "assets") {
        const assets = (await dbList<Record<string, any>>("creative-assets"))
            .filter((item) => item.conversationId === id && item.status !== "deleted")
            .sort((left, right) => Number(left.createdAt || 0) - Number(right.createdAt || 0));
        return jsonResponse({ code: 0, data: { assets }, msg: "OK" });
    }
    if (init?.method === "PATCH") {
        const next = { ...conversation, ...(await readJson(init)), updatedAt: Date.now() };
        creativeConversations.set(id, next);
        await dbPut("creative-conversations", next);
        return jsonResponse({ code: 0, data: { conversation: next }, msg: "OK" });
    }
    return jsonResponse({ code: 0, data: { conversation }, msg: "OK" });
}

async function deleteStaticCreativeConversation(conversationId: string) {
    if (!conversationId) return;
    await dbDelete("creative-conversations", conversationId);
    const [messages, assets, runs] = await Promise.all([
        dbList<Record<string, any>>("creative-messages"),
        dbList<Record<string, any>>("creative-assets"),
        dbList<Record<string, any>>("agent-runs"),
    ]);
    await Promise.all([
        ...messages.filter((item) => item.conversationId === conversationId).map((item) => dbDelete("creative-messages", item.id)),
        ...assets.filter((item) => item.conversationId === conversationId).map((item) => dbDelete("creative-assets", item.id)),
        ...runs.filter((item) => item.conversationId === conversationId).map((item) => dbDelete("agent-runs", item.id)),
    ]);
    creativeConversations.delete(conversationId);
    for (const [runId, run] of agentRuns) if (run.conversationId === conversationId) agentRuns.delete(runId);
}

async function handleCreativeAssetUpload(init?: RequestInit) {
    if (!(init?.body instanceof FormData)) return jsonResponse({ code: 400, data: null, msg: "上传内容格式不正确" }, 400);
    const conversationId = String(init.body.get("conversationId") || "").trim();
    const file = init.body.get("file");
    if (!conversationId || !(file instanceof Blob)) return jsonResponse({ code: 400, data: null, msg: "创作会话和文件不能为空" }, 400);
    if (file.size > 20 * 1024 * 1024) return jsonResponse({ code: 413, data: null, msg: "单个素材不能超过 20MB" }, 413);
    const dataUrl = await blobToDataUrl(file);
    const id = `asset-${nanoid()}`;
    const now = Date.now();
    const asset = {
        id,
        userId: "static-local",
        conversationId,
        sourceRunId: "upload",
        ordinal: (await dbList<Record<string, any>>("creative-assets")).filter((item) => item.conversationId === conversationId).length,
        type: file.type.startsWith("video/") ? "video" : file.type.startsWith("audio/") ? "audio" : "image",
        status: "ready",
        title: file instanceof File && file.name ? file.name : "上传素材",
        storageKind: "local",
        storageKey: `creative/${id}`,
        serverUrl: dataUrl,
        dataUrl,
        mimeType: file.type || "application/octet-stream",
        bytes: file.size,
        metadata: { source: "upload" },
        createdAt: now,
        updatedAt: now,
    };
    await dbPut("creative-assets", asset);
    return jsonResponse({ code: 0, data: { asset }, msg: "素材已上传" });
}


function normalizeStaticImageSize(value: unknown, quality: unknown) {
    const text = String(value || "").trim();
    if (!text || /^auto$/i.test(text)) return "auto";
    const dimensions = text.match(/^(\d+)\s*[x*×]\s*(\d+)$/i);
    if (dimensions) return `${Number(dimensions[1])}x${Number(dimensions[2])}`;
    const ratio = text.match(/^(\d+(?:\.\d+)?)\s*:\s*(\d+(?:\.\d+)?)$/);
    if (!ratio) return text;
    const ratioWidth = Number(ratio[1]);
    const ratioHeight = Number(ratio[2]);
    const qualityValue = String(quality || "").toLowerCase();
    // 【修复】支持更多质量描述：4K/2K/高清/超高清等
    let base = 1024;
    if (/4k|4096|超高清|超清|high/.test(qualityValue)) base = 2880;
    else if (/2k|2048|高清|medium/.test(qualityValue)) base = 2048;
    else if (/1k|1024|标清|标准|low/.test(qualityValue)) base = 1024;
    const scale = Math.max(1, Math.sqrt(655360 / (base * base)));
    let shortSide = Math.ceil((base * scale) / 16) * 16;
    let longSide = Math.ceil((shortSide * Math.max(ratioWidth, ratioHeight) / Math.min(ratioWidth, ratioHeight)) / 16) * 16;
    // 【修复】限制最大尺寸，确保不超过常见中转站支持的范围（最大 2048 短边）
    const MAX_SHORT_SIDE = 4096;
    if (shortSide > MAX_SHORT_SIDE) {
        const downscale = MAX_SHORT_SIDE / shortSide;
        shortSide = MAX_SHORT_SIDE;
        longSide = Math.ceil((longSide * downscale) / 16) * 16;
    }
    return ratioWidth >= ratioHeight ? `${longSide}x${shortSide}` : `${shortSide}x${longSide}`;
}

function normalizeImageResponse(payload: Record<string, any>, mediaBaseUrl = "") {
    const results: Array<{ dataUrl: string; remoteUrl?: string }> = [];
    const seen = new Set<string>();
    const add = (dataUrl: string, remoteUrl?: string) => {
        if (!dataUrl || seen.has(dataUrl)) return;
        seen.add(dataUrl);
        results.push({ dataUrl, remoteUrl: remoteUrl || (/^https?:\/\//i.test(dataUrl) ? dataUrl : undefined) });
    };
    const visit = (value: unknown, key = "", depth = 0) => {
        if (depth > 6 || value === null || value === undefined) return;
        if (typeof value === "string") {
            const trimmed = value.trim();
            if (/^data:image\//i.test(trimmed) || /^https?:\/\//i.test(trimmed)) add(trimmed);
            else if (mediaBaseUrl && /^\/(?!\/)/.test(trimmed)) {
                try { add(new URL(trimmed, `${mediaBaseUrl.replace(/\/+$/, "")}/`).toString()); } catch { /* Ignore malformed provider media URLs. */ }
            }
            else if (/(?:b64|base64|image_base64)/i.test(key) && /^[A-Za-z0-9+/=\r\n]{64,}$/.test(trimmed)) add(`data:image/png;base64,${trimmed.replace(/\s+/g, "")}`);
            return;
        }
        if (Array.isArray(value)) {
            value.forEach((item) => visit(item, key, depth + 1));
            return;
        }
        if (typeof value !== "object") return;
        Object.entries(value as Record<string, unknown>).forEach(([childKey, childValue]) => visit(childValue, childKey, depth + 1));
    };
    visit(payload);
    return { ...results[0], results };
}

function textContent(value: unknown): string {
    if (typeof value === "string") return value.trim();
    if (Array.isArray(value)) return value.map((item) => (typeof item === "string" ? item : item && typeof item === "object" ? textContent((item as Record<string, unknown>).text || (item as Record<string, unknown>).content) : "")).filter(Boolean).join("\n");
    if (value && typeof value === "object") return textContent((value as Record<string, unknown>).text || (value as Record<string, unknown>).content);
    return "";
}

function parseJsonText(value: string): Record<string, any> {
    const cleaned = value.trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");
    try { return JSON.parse(cleaned) as Record<string, any>; } catch {
        const start = cleaned.indexOf("{");
        const end = cleaned.lastIndexOf("}");
        if (start >= 0 && end > start) return JSON.parse(cleaned.slice(start, end + 1)) as Record<string, any>;
        throw new Error("模型没有返回有效 JSON");
    }
}

function configForConnection(connectionId: string, model: string) {
    return { model, connectionId: connectionId || connectionIdFromModel(model) || getActiveCreativeApiConnection()?.id || "" };
}

async function chatCompletion(config: { model: string; connectionId?: string }, messages: unknown[], options: { json?: boolean; reasoning?: boolean; signal?: AbortSignal } = {}) {
    const base = { model: modelName(config.model), messages, stream: false } as Record<string, unknown>;
    const requests: Record<string, unknown>[] = [];
    if (options.reasoning) {
        requests.push({ ...base, ...(options.json ? { response_format: { type: "json_object" } } : {}), reasoning_effort: "high" });
        requests.push({ ...base, reasoning_effort: "high" });
    }
    if (options.json) requests.push({ ...base, response_format: { type: "json_object" } });
    requests.push(base);
    let response: Response | undefined;
    for (const body of requests) {
        response = await newApiFetch("/v1/chat/completions", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body), signal: options.signal }, config.connectionId);
        if (response.ok) return response;
        const error = await readError(response, "文本生成失败");
        if (!shouldRetryChatRequest(response.status, error)) return new Response(JSON.stringify({ error }), { status: response.status, headers: { "Content-Type": "application/json" } });
    }
    return response!;
}

/**
 * 自适应聊天请求：自动检测中转站是否支持流式，兼容所有中转站
 * 1. 先尝试流式请求（stream: true）
 * 2. 根据响应头 Content-Type 判断是 SSE 还是 JSON
 * 3. 如果是 SSE，用流式解析；如果是 JSON，用非流式解析
 * 4. 如果流式请求失败，自动回退到非流式请求
 * 5. 更健壮的 SSE 解析，兼容不同格式
 */

/**
 * 【多模型兼容】从 API 响应 payload 中提取内容
 * 支持：
 * - 标准 message.content
 * - output_text
 * - tool_calls[].function.arguments
 * - function_call.arguments
 * - 多种中转站自定义格式
 */
function extractContentFromPayload(payload: Record<string, any>): string {
    // 1. 标准 message.content
    const messageContent = payload.choices?.[0]?.message?.content;
    if (typeof messageContent === "string" && messageContent.trim()) return messageContent;

    // 2. output_text（一些中转站使用）
    if (typeof payload.output_text === "string" && payload.output_text.trim()) return payload.output_text;

    // 3. 标准 tool_calls 格式
    const toolCalls = payload.choices?.[0]?.message?.tool_calls;
    if (Array.isArray(toolCalls) && toolCalls.length > 0) {
        for (const call of toolCalls) {
            const args = call?.function?.arguments;
            if (typeof args === "string" && args.trim()) return args;
            if (args && typeof args === "object") {
                try { return JSON.stringify(args); } catch { /* ignore */ }
            }
        }
    }

    // 4. 旧版 function_call 格式
    const functionCall = payload.choices?.[0]?.message?.function_call;
    if (functionCall?.arguments) {
        const args = functionCall.arguments;
        if (typeof args === "string" && args.trim()) return args;
        if (args && typeof args === "object") {
            try { return JSON.stringify(args); } catch { /* ignore */ }
        }
    }

    // 5. 一些中转站把 tool_calls 放在 message.tools 或 message.calls 中
    const alternativeCallArrays = [
        payload.choices?.[0]?.message?.tools,
        payload.choices?.[0]?.message?.calls,
        payload.choices?.[0]?.message?.function_calls,
    ];
    for (const arr of alternativeCallArrays) {
        if (Array.isArray(arr) && arr.length > 0) {
            for (const call of arr) {
                const args = call?.function?.arguments || call?.arguments || call?.args;
                if (typeof args === "string" && args.trim()) return args;
                if (args && typeof args === "object") {
                    try { return JSON.stringify(args); } catch { /* ignore */ }
                }
            }
        }
    }

    // 6. 直接在 payload 中返回结果（一些中转站的自定义格式）
    const directFields = ["result", "data", "response", "answer", "text"];
    for (const field of directFields) {
        const value = payload[field];
        if (typeof value === "string" && value.trim()) return value;
        if (value && typeof value === "object" && value.content) {
            if (typeof value.content === "string" && value.content.trim()) return value.content;
        }
    }

    return "";
}

async function streamChatCompletion(config: { model: string; connectionId?: string }, messages: unknown[], options: { json?: boolean; reasoning?: boolean; signal?: AbortSignal } = {}): Promise<{ ok: boolean; status: number; content: string; error?: string }> {
    const model = modelName(config.model);

    // 构建请求变体（reasoning → json → 默认）
    const buildRequests = (stream: boolean): Record<string, unknown>[] => {
        const base = { model, messages, stream } as Record<string, unknown>;
        const requests: Record<string, unknown>[] = [];
        if (options.reasoning) {
            requests.push({ ...base, ...(options.json ? { response_format: { type: "json_object" } } : {}), reasoning_effort: "high" });
            requests.push({ ...base, reasoning_effort: "high" });
        }
        if (options.json) requests.push({ ...base, response_format: { type: "json_object" } });
        requests.push(base);
        return requests;
    };

    // 解析 SSE 流式响应
    const parseSseStream = async (response: Response): Promise<string> => {
        const reader = response.body?.getReader();
        if (!reader) throw new Error("响应流不可读");
        const decoder = new TextDecoder();
        let buffer = "";
        let content = "";
        let reasoningContent = "";
        let functionCallArguments = "";
        try {
            while (true) {
                const { done, value } = await reader.read();
                if (done) break;
                buffer += decoder.decode(value, { stream: true });
                // 兼容 \n\n 和 \r\n\r\n 作为事件分隔符
                const events = buffer.split(/\r?\n\r?\n/);
                buffer = events.pop() || "";
                for (const event of events) {
                    const lines = event.split(/\r?\n/);
                    for (const line of lines) {
                        const trimmed = line.trim();
                        if (!trimmed.startsWith("data:")) continue;
                        const data = trimmed.slice(5).trim();
                        if (!data || data === "[DONE]") continue;
                        try {
                            const payload = JSON.parse(data) as Record<string, any>;
                            const delta = payload.choices?.[0]?.delta;
                            if (delta?.content) content += String(delta.content);
                            if (delta?.reasoning_content) reasoningContent += String(delta.reasoning_content);

                            // 【多模型兼容】支持 function call / tool call 格式
                            const toolCalls = delta?.tool_calls;
                            if (Array.isArray(toolCalls) && toolCalls.length > 0) {
                                for (const call of toolCalls) {
                                    const args = call?.function?.arguments;
                                    if (typeof args === "string") functionCallArguments += args;
                                    else if (args && typeof args === "object") {
                                        try { functionCallArguments += JSON.stringify(args); } catch { /* ignore */ }
                                    }
                                }
                            }
                            const functionCall = delta?.function_call;
                            if (functionCall?.arguments) {
                                const args = functionCall.arguments;
                                if (typeof args === "string") functionCallArguments += args;
                                else if (args && typeof args === "object") {
                                    try { functionCallArguments += JSON.stringify(args); } catch { /* ignore */ }
                                }
                            }
                            const message = payload.choices?.[0]?.message;
                            if (message?.tool_calls && Array.isArray(message.tool_calls)) {
                                for (const call of message.tool_calls) {
                                    const args = call?.function?.arguments;
                                    if (typeof args === "string" && !functionCallArguments) functionCallArguments = args;
                                    else if (args && typeof args === "object" && !functionCallArguments) {
                                        try { functionCallArguments = JSON.stringify(args); } catch { /* ignore */ }
                                    }
                                }
                            }

                            // 兼容一些中转站使用 output_text 字段
                            if (payload.output_text && !content) content = String(payload.output_text);
                            // 兼容 choices[0].message.content（非标准流式）
                            if (!content && payload.choices?.[0]?.message?.content) content += String(payload.choices[0].message.content);
                        } catch {
                            // 忽略无法解析的 SSE 数据块
                        }
                    }
                }
            }
        } finally {
            reader.releaseLock();
        }
        // 【多模型兼容】优先返回 content，其次返回 function call arguments，最后返回 reasoning content
        return content || functionCallArguments || reasoningContent;
    };

    // 尝试流式请求
    const streamRequests = buildRequests(true);
    for (const body of streamRequests) {
        try {
            const response = await newApiFetch("/v1/chat/completions", {
                method: "POST",
                headers: { "Content-Type": "application/json", Accept: "text/event-stream, application/json" },
                body: JSON.stringify(body),
                signal: options.signal,
            }, config.connectionId);

            if (!response.ok) {
                const error = await readError(response, "文本生成失败");
                // 如果是 400/415 等不支持流式的错误，跳出循环，尝试非流式
                if ([400, 415, 422].includes(response.status) && /stream|not support|unsupported|unknown field/i.test(error)) break;
                if (!shouldRetryChatRequest(response.status, error)) return { ok: false, status: response.status, content: "", error };
                continue;
            }

            const contentType = response.headers.get("content-type") || "";
            // 根据 Content-Type 判断是 SSE 还是 JSON
            if (contentType.includes("text/event-stream")) {
                const content = await parseSseStream(response);
                if (content.trim()) return { ok: true, status: 200, content };
                // SSE 解析后内容为空，继续尝试下一个请求变体
                continue;
            } else {
                // 非流式 JSON 响应，直接解析
                const payload = await response.json() as Record<string, any>;
                const content = extractContentFromPayload(payload);
                if (String(content).trim()) return { ok: true, status: 200, content: String(content) };
                continue;
            }
        } catch (cause) {
            // 网络错误或其他异常，继续尝试下一个请求变体
            if (options.signal?.aborted) return { ok: false, status: 0, content: "", error: "请求已取消" };
            continue;
        }
    }

    // 流式请求全部失败，自动回退到非流式请求
    const nonStreamRequests = buildRequests(false);
    for (const body of nonStreamRequests) {
        try {
            const response = await newApiFetch("/v1/chat/completions", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(body),
                signal: options.signal,
            }, config.connectionId);

            if (!response.ok) {
                const error = await readError(response, "文本生成失败");
                if (!shouldRetryChatRequest(response.status, error)) return { ok: false, status: response.status, content: "", error };
                continue;
            }

            const payload = await response.json() as Record<string, any>;
            const content = extractContentFromPayload(payload);
            if (String(content).trim()) return { ok: true, status: 200, content: String(content) };
        } catch (cause) {
            if (options.signal?.aborted) return { ok: false, status: 0, content: "", error: "请求已取消" };
            continue;
        }
    }

    return { ok: false, status: 502, content: "", error: "所有请求方式均失败，请检查中转站配置或网络连接" };
}

function shouldRetryChatRequest(status: number, message: string) {
    return [400, 404, 415, 422, 500, 502, 503, 504].includes(status) && /openai_error|response[_ -]?format|json_object|reasoning[_ -]?effort|unsupported|not supported|invalid|unknown field|unrecognized/i.test(message);
}

function staticUser() {
    return { id: "static-local", accountId: "static-local", username: "local-workspace", displayName: "本地工作台", bio: "", role: "user", adminPermissions: [], status: "active", planId: "local", planName: "static", hasActivePlan: true, pointsBalance: 0, mfaEnabled: false };
}

function jsonResponse(payload: unknown, status = 200) { return new Response(JSON.stringify(payload), { status, headers: { "Content-Type": "application/json" } }); }
async function readJson(init?: RequestInit) { if (!init?.body) return {}; if (typeof init.body === "string") return JSON.parse(init.body || "{}"); return {}; }
async function readError(response: Response, fallback: string) {
    const text = await response.text();
    const key = getCreativeApiKey();
    const redact = (value: unknown) => {
        const message = String(value || fallback);
        return (key ? message.replaceAll(key, "[已隐藏]") : message).slice(0, 300);
    };
    try {
        const payload = JSON.parse(text) as unknown;
        return redact(extractErrorMessage(payload) || fallback);
    } catch {
        return redact(text);
    }
}

function extractErrorMessage(value: unknown, seen = new Set<unknown>()): string {
    if (!value || seen.has(value)) return "";
    if (typeof value === "string") return value.trim();
    if (Array.isArray(value)) {
        for (const item of value) {
            const message = extractErrorMessage(item, seen);
            if (message) return message;
        }
        return "";
    }
    if (typeof value !== "object") return "";
    seen.add(value);
    const record = value as Record<string, unknown>;
    for (const key of ["message", "detail", "msg", "error", "errors", "cause"]) {
        const message = extractErrorMessage(record[key], seen);
        if (message) return message;
    }
    return "";
}

function normalizeApiBaseUrl(value: string) {
    const raw = value.trim() || window.location.origin;
    const withProtocol = /^[a-z][a-z\d+.-]*:\/\//i.test(raw) ? raw : `https://${raw}`;
    const parsed = new URL(withProtocol, window.location.origin);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") throw new Error("中转站 URL 必须使用 HTTP 或 HTTPS");
    parsed.search = "";
    parsed.hash = "";
    let pathname = parsed.pathname.replace(/\/+$/, "");
    if (/\/v1(?:beta)?$/i.test(pathname)) pathname = pathname.replace(/\/v1(?:beta)?$/i, "").replace(/\/+$/, "");
    return `${parsed.origin}${pathname}`;
}

function readConnections(): CreativeApiConnection[] {
    const raw = sessionStorage.getItem(API_CONNECTIONS_SESSION) || localStorage.getItem(API_CONNECTIONS_REMEMBERED);
    if (!raw) return [];
    try {
        const parsed = JSON.parse(raw) as unknown;
        if (!Array.isArray(parsed)) return [];
        return parsed.flatMap((item) => {
            if (!item || typeof item !== "object") return [];
            const value = item as Record<string, unknown>;
            const key = typeof value.key === "string" ? value.key.trim() : "";
            const baseUrl = typeof value.baseUrl === "string" ? value.baseUrl : "";
            if (!key || !baseUrl) return [];
            try {
                return [{ id: String(value.id || nanoid()), name: String(value.name || "中转站"), baseUrl: normalizeApiBaseUrl(baseUrl), key }];
            } catch {
                return [];
            }
        });
    } catch {
        return [];
    }
}

function getCreativeApiConnection(id?: string) {
    const connections = getCreativeApiConnections();
    return connections.find((connection) => connection.id === id) || getActiveCreativeApiConnection();
}

async function handleAudioTask(init?: RequestInit) {
    const input = await readJson(init);
    const config = input.config || {};
    const response = await newApiFetch("/v1/audio/speech", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ model: config.model, input: input.prompt || "", voice: config.voice || "alloy", response_format: config.format || "mp3", speed: Number(config.speed) || 1 }) }, String(config.connectionId || ""));
    if (!response.ok) return jsonResponse({ error: await readError(response, "音频生成失败") }, response.status);
    const taskId = `audio-${nanoid()}`;
    const blob = await response.blob();
    const result = { url: await blobToDataUrl(blob), mimeType: blob.type || "audio/mpeg" };
    taskResults.set(taskId, result);
    taskConnections.set(taskId, String(config.connectionId || ""));
    return jsonResponse({ task: { id: taskId, model: config.model, status: "success", result } });
}

async function handleAudioTaskById(id: string) {
    return jsonResponse({ task: { id, status: "success", result: taskResults.get(id) } });
}

function videoApiFetch(path: string, init: RequestInit = {}, connectionId?: string, baseUrlOverride?: string) {
    const headers = new Headers(init.headers);
    const connection = connectionId ? getCreativeApiConnections().find((item) => item.id === connectionId) : getActiveCreativeApiConnection();
    const key = connection?.key || getCreativeApiKey();
    if (key) headers.set("Authorization", `Bearer ${key}`);
    const baseUrl = connection?.baseUrl || baseUrlOverride || getCreativeApiBaseUrl();
    // Video paths below are absolute API paths (for example /v1/videos).
    // Users may configure either the gateway root or a URL ending in /v1;
    // strip that suffix so it is never duplicated as /v1/v1/....
    const target = buildJui87VideoApiUrl(baseUrl, path);
    // 【修复】直接请求中转站，不走代理，避免代理端点返回错误响应
    return originalFetch(target, { ...init, headers });
}
function dataUrlToBlob(value: string) {
    const match = value.match(/^data:([^;,]+)?(?:;base64)?,(.*)$/s);
    if (!match) return new Blob([value], { type: "application/octet-stream" });
    const mimeType = match[1] || "application/octet-stream";
    if (!value.includes(";base64,")) return new Blob([decodeURIComponent(match[2])], { type: mimeType });
    const binary = atob(match[2]);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
    return new Blob([bytes], { type: mimeType });
}
function blobToDataUrl(blob: Blob) { return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result || "")); reader.onerror = () => reject(new Error("读取文件失败")); reader.readAsDataURL(blob); }); }

type StoreName = "canvas" | "media" | "skills" | "agent-runs" | "creative-conversations" | "creative-messages" | "creative-assets" | "video-tasks" | "image-tasks";
function openDb() {
    if (dbPromise) return dbPromise;
    dbPromise = new Promise<IDBDatabase>((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        let settled = false;
        const timeout = window.setTimeout(() => {
            if (settled) return;
            settled = true;
            dbPromise = null;
            reject(new Error("本地数据库被其他标签页占用，请关闭其他创作工作台标签页后重试"));
        }, 5_000);
        request.onupgradeneeded = () => {
            const db = request.result;
            if (!db.objectStoreNames.contains("canvas")) db.createObjectStore("canvas", { keyPath: "id" });
            if (!db.objectStoreNames.contains("media")) db.createObjectStore("media", { keyPath: "id" });
            if (!db.objectStoreNames.contains("skills")) db.createObjectStore("skills", { keyPath: "id" });
            if (!db.objectStoreNames.contains("agent-runs")) db.createObjectStore("agent-runs", { keyPath: "id" });
            if (!db.objectStoreNames.contains("creative-conversations")) db.createObjectStore("creative-conversations", { keyPath: "id" });
            if (!db.objectStoreNames.contains("creative-messages")) db.createObjectStore("creative-messages", { keyPath: "id" });
            if (!db.objectStoreNames.contains("creative-assets")) db.createObjectStore("creative-assets", { keyPath: "id" });
            if (!db.objectStoreNames.contains("video-tasks")) db.createObjectStore("video-tasks", { keyPath: "id" });
            if (!db.objectStoreNames.contains("image-tasks")) db.createObjectStore("image-tasks", { keyPath: "id" });
        };
        request.onsuccess = () => {
            const db = request.result;
            if (settled) {
                db.close();
                return;
            }
            settled = true;
            window.clearTimeout(timeout);
            db.onversionchange = () => {
                db.close();
                dbPromise = null;
            };
            resolve(db);
        };
        request.onerror = () => {
            if (settled) return;
            settled = true;
            window.clearTimeout(timeout);
            dbPromise = null;
            reject(request.error || new Error("本地数据库打开失败"));
        };
    });
    return dbPromise;
}
async function dbList<T>(store: StoreName) { const db = await openDb(); return new Promise<T[]>((resolve, reject) => { const request = db.transaction(store, "readonly").objectStore(store).getAll(); request.onsuccess = () => resolve(request.result as T[]); request.onerror = () => reject(request.error); }); }
async function dbGet<T>(store: StoreName, id: string) { const db = await openDb(); return new Promise<T | undefined>((resolve, reject) => { const request = db.transaction(store, "readonly").objectStore(store).get(id); request.onsuccess = () => resolve(request.result as T | undefined); request.onerror = () => reject(request.error); }); }
async function dbPut(store: StoreName, value: unknown) { const db = await openDb(); return new Promise<void>((resolve, reject) => { const request = db.transaction(store, "readwrite").objectStore(store).put(value); request.onsuccess = () => resolve(); request.onerror = () => reject(request.error); }); }
async function dbDelete(store: StoreName, id: string) { const db = await openDb(); return new Promise<void>((resolve, reject) => { const request = db.transaction(store, "readwrite").objectStore(store).delete(id); request.onsuccess = () => resolve(); request.onerror = () => reject(request.error); }); }


